teste('leitor-conferir-por-estrutura', async (b, t) => {
  // "Conferir a leitura" mostrava o desenho inteiro numa caixa só: uma linha
  // solta longe das estruturas encolhia tudo, e a treliça virava um risco.
  // Agora cada estrutura tem o seu quadro na largura toda (com vão, altura e
  // peças), o que sobrou fora vai num quadro próprio, e o desenho inteiro
  // continua a um clique, com zoom.
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, trelicaTeste('conferir_est', { fora: true }), { viewport: { width: 1400, height: 900 } });
  const r = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms));
    const card = document.querySelector('.conf-card'), cw = card.getBoundingClientRect().width;
    const tiles = [...document.querySelectorAll('#conferir .conf-tile')];
    const est = tiles.find(x => !x.classList.contains('fora')), fora = tiles.find(x => x.classList.contains('fora'));
    const desenho = est && est.querySelector('svg path');
    const larg = desenho ? desenho.getBoundingClientRect().width : 0;
    const out = { n: tiles.length, cab: est ? est.innerText.replace(/\s+/g, ' ') : '', fora: fora ? fora.innerText.replace(/\s+/g, ' ') : '', ocupa: Math.round(larg / cw * 100) };
    const bt = document.querySelector('#conferir [data-conf-modo="tudo"]'); if (bt) bt.click(); await esp(150);
    const svg = document.querySelector('#conferir .conf-tudo svg');
    out.tudo = !!svg; out.marca = !!(svg && svg.querySelector('.conf-marca-fora'));
    if (svg) { const v0 = svg.getAttribute('viewBox'); const q = svg.getBoundingClientRect();
      svg.dispatchEvent(new WheelEvent('wheel', { deltaY: -200, clientX: q.x + q.width / 2, clientY: q.y + q.height / 2, bubbles: true, cancelable: true })); await esp(50);
      out.zoom = v0 !== svg.getAttribute('viewBox'); out.altura = Math.round(q.height); }
    return out;
  }).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r) + ' ' + erros.join(' | ');
  t.ok('um quadro por estrutura e um para o que ficou fora', !r.erro && r.n === 2, J);
  t.ok('a treliça ocupa a largura do quadro (≥ 70%)', !r.erro && r.ocupa >= 70, J);
  t.ok('o quadro diz nome, quantidade, vão e altura', !r.erro && /TRELIÇA 01/.test(r.cab) && /2×/.test(r.cab) && /vão 12,00 m/.test(r.cab) && /altura 0,80 m/.test(r.cab), J);
  t.ok('a linha fora de estrutura tem quadro próprio, com onde achar', !r.erro && /fora de estrutura/i.test(r.fora) && /X\s*2\.?150/.test(r.fora), J);
  t.ok('"Desenho inteiro" mostra tudo, marca o que está fora e aproxima com a roda', !r.erro && r.tudo && r.marca && r.zoom && r.altura >= 380, J);
  t.ok('sem erro na página', !erros.length, J);
  await ctx.close();
});

teste('leitor-suporte-de-terca-ignorado', async (b, t) => {
  // o suporte de terça (quadrado/retângulo sobre o banzo) aparecia em
  // "Conferir a leitura" como linha de peça -- e, sozinho, como "linha fora
  // de estrutura". Não é peça: nem no conferir, nem no detalhamento.
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const le = async (arq) => {
    const { ctx, pg, erros } = await leitorImporta(b, arq, { viewport: { width: 1400, height: 900 } });
    const r = await pg.evaluate(() => { const T = window.__leitorTeste; if (!T) return { erro: 'sem gancho' };
      const s = (T.secoes().secoes || [])[0];
      return { pecas: s ? s.gr.reduce((a, g) => a + g.qtd, 0) : -1, grupos: s ? s.gr.map(g => g.qtd + '×' + g.corte).join(' ') : '',
        fora: !!document.querySelector('#conferir .conf-tile.fora'), res: (document.querySelector('#conferir .conf-res') || {}).innerText || '',
        cab: ((document.querySelector('#conferir .conf-tile:not(.fora)') || {}).innerText || '').replace(/\s+/g, ' ') }; }).catch(e => ({ erro: e.message }));
    await ctx.close(); return { r, erros };
  };
  const base = await le(trelicaTeste('sup_base')), com = await le(trelicaTeste('sup_com', { suportes: true }));
  const J = JSON.stringify({ base: base.r, com: com.r }) + ' ' + base.erros.concat(com.erros).join(' | ');
  t.ok('conferir: o suporte sozinho não vira "linha fora de estrutura"', !com.r.erro && !com.r.fora && /nenhuma linha de peça sobrando/.test(com.r.res), J);
  t.ok('conferir: o suporte sobre o banzo não conta como peça interna', !com.r.erro && com.r.cab.includes('2 de banzo · 13 internas'), J);
  t.ok('detalhamento: as mesmas peças com e sem suporte', !com.r.erro && base.r.pecas > 0 && com.r.grupos === base.r.grupos, J);
  t.ok('sem erro na página', !base.erros.length && !com.erros.length, J);
});

/* lê o "Conferir a leitura" de uma estrutura e o detalhamento dela */
async function leitorConfere(b, arq, antes) {
  const { ctx, pg, erros } = await leitorImporta(b, arq, { viewport: { width: 1400, height: 900 }, antes });
  const r = await pg.evaluate(() => { const T = window.__leitorTeste; if (!T) return { erro: 'sem gancho' };
    const s = (T.secoes().secoes || [])[0];
    const tile = document.querySelector('#conferir .conf-tile:not(.fora)');
    const tx = e => e ? e.innerText.replace(/\s+/g, ' ') : '';
    return { det: s ? { b: s.banzos.length, i: s.internos.length } : null,
      cab: tx(tile && tile.querySelector('.conf-med')), ign: tx(tile && tile.querySelector('.conf-ign')),
      lista: tile ? [...tile.querySelectorAll('.conf-lista li')].map(tx) : [], marcas: tile ? tile.querySelectorAll('svg .conf-marca').length : 0,
      notas: tx(tile && tile.querySelector('.conf-notas')), res: tx(document.querySelector('#conferir .conf-res')) }; }).catch(e => ({ erro: e.message }));
  await ctx.close(); return { r, erros };
}

teste('leitor-prancha-montagem-pdf', async (b, t) => {
  // "PDF gerado pela prancha montagem gerando folha em branco / Em uma das
  // folhas precisa ter o desenho da tesoura completa para o montador ver ela
  // toda com os códigos / Ao clicar em ver em mm ou ver em cm também precisa
  // alterar no desenho". O PDF saía branco, TRECHO 1/2, branco, TRECHO 2/2,
  // branco: a prancha de 100% de largura ficava mais alta que a folha menos
  // o pé da papelaria e cada uma pulava para a página seguinte.
  if (!fs.existsSync(path.join(FIX_LEITOR, 'caso4.dxf')) || !fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, path.join(FIX_LEITOR, 'caso4.dxf'), { viewport: { width: 1400, height: 900 } });
  const gera = async (cm) => pg.evaluate(async (cm) => {
    let h = null; window.rmDesktop = { salvarPDF: async (x) => { h = x; return { ok: true }; } };
    window.confirm = () => true;
    document.getElementById('detalhar').click();
    if (cm && /cm/.test(document.getElementById('dtUnid').textContent)) document.getElementById('dtUnid').click();
    await new Promise(x => setTimeout(x, 300));
    document.getElementById('dtPrancha').click(); await new Promise(x => setTimeout(x, 900));
    const tit = [...document.querySelectorAll('#dtPranchas .prancha svg > text:first-of-type')].map(x => x.textContent);
    const cods = [...document.querySelectorAll('#dtPranchas .prancha svg text[fill="#D53309"]')].map(x => x.textContent).filter(x => /-P\d/.test(x));
    return { h, tit, cods };
  }, cm).catch(e => ({ erro: e.message }));
  const conta = async (h) => {
    const p = await ctx.newPage();
    await p.setContent(h || '<p>sem documento</p>');
    const pdf = await p.pdf({ preferCSSPageSize: true, printBackground: true }).catch(() => null);
    await p.close();
    return pdf ? (pdf.toString('latin1').match(/\/Type\s*\/Page[^s]/g) || []).length : 0;
  };
  const mm = await gera(false);
  if (process.env.PRANCHA_DOC) fs.writeFileSync(process.env.PRANCHA_DOC, mm.h || '');
  mm.paginas = await conta(mm.h); delete mm.h;
  const J = JSON.stringify({ paginas: mm.paginas, erro: mm.erro, tit: mm.tit, cods: (mm.cods || []).slice(0, 6) }) + ' ' + erros.join(' | ');
  t.ok('uma página por prancha, sem folha em branco', !mm.erro && mm.tit.length > 1 && mm.paginas === mm.tit.length, J);
  const inteira = mm.tit.filter(x => !/TRECHO/.test(x)), trechos = mm.tit.filter(x => /TRECHO/.test(x));
  // cada estrutura: a completa primeiro, depois os seus trechos
  const porEst = {}; mm.tit.forEach(x => { const e = (x.match(/Estrutura (\w+)/) || [])[1]; (porEst[e] = porEst[e] || []).push(x); });
  t.ok('com a tesoura em trechos, uma folha traz a tesoura completa antes deles', trechos.length >= 2 && Object.values(porEst).every(l => l.length === 1 ||
    (/TESOURA COMPLETA/.test(l[0]) && l.slice(1).every(x => /TRECHO/.test(x)) && inteira.filter(x => l.includes(x)).length === 1)), J);
  t.ok('códigos em mm na prancha', mm.cods.length > 0 && mm.cods.every(x => /\d+MM$/.test(x)), J);
  const cm = await gera(true);
  if (process.env.PRANCHA_DOC) fs.writeFileSync(process.env.PRANCHA_DOC.replace(/\.html$/, '-cm.html'), cm.h || '');
  cm.paginas = await conta(cm.h); delete cm.h;
  const J2 = JSON.stringify({ paginas: cm.paginas, erro: cm.erro, n: [(cm.cods || []).length, mm.cods.length], cods: (cm.cods || []).slice(0, 6) });
  const emMM = {}; mm.cods.forEach(x => { emMM[x.replace(/-\d+MM$/, '')] = +x.match(/(\d+)MM$/)[1]; });
  t.ok('"Ver em cm": os códigos da prancha saem em cm, mesma peça e mesma medida', !cm.erro && cm.cods.length === mm.cods.length && cm.cods.every(x => /\d+,\dCM$/.test(x) &&
    Math.abs(parseFloat(x.match(/([\d,]+)CM$/)[1].replace(',', '.')) * 10 - emMM[x.replace(/-[\d,]+CM$/, '')]) < 0.51), J2);
  t.ok('em cm também uma página por prancha', cm.paginas === (cm.tit || []).length, J2 + ' ' + (cm.tit || []).length);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

/* lê as pranchas montagem já geradas: títulos, textos azuis e laranja */
async function leitorPranchasCotas(pg, cm) {
  return pg.evaluate(async (cm) => {
    window.rmDesktop = { salvarPDF: async (x) => { window.__docPrancha = x; return { ok: true }; } }; window.confirm = () => true;
    document.getElementById('detalhar').click();
    const u = document.getElementById('dtUnid');
    if (cm === /cm/.test(u.textContent)) u.click();
    await new Promise(x => setTimeout(x, 300));
    document.getElementById('dtPrancha').click(); await new Promise(x => setTimeout(x, 900));
    return [...document.querySelectorAll('#dtPranchas .prancha')].map(pr => {
      const az = [...pr.querySelectorAll('svg text[fill="#1d4f91"]')].map(x => x.textContent);
      const lj = [...pr.querySelectorAll('svg text[fill="#e0601a"]')].map(x => x.textContent);
      return { tit: pr.querySelector('svg > text').textContent, ps: az.filter(x => /^P\d+$/.test(x)), cotas: az.filter(x => /^[\d.,]+$/.test(x)),
        ref: az.filter(x => / da /.test(x)), gerais: az.filter(x => /comprimento total|banzo superior/.test(x)), alturas: az.filter(x => /^[\d.,]+$/.test(x)).length,
        laranja: lj, triangulos: pr.querySelectorAll('svg path[fill="#e0601a"]').length, inicio: pr.querySelectorAll('svg circle[fill="#1d4f91"]').length };
    });
  }, cm).catch(e => [{ erro: e.message }]);
}

teste('leitor-prancha-cota-verticais', async (b, t) => {
  // Pedido: cota entre as verticais nos trechos, na horizontal, ao longo do
  // banzo de baixo; começa na cumeeira e vai para os dois lados, da aba
  // interna de uma vertical até a aba interna da próxima (a face do lado da
  // ponta baixa). Na folha completa: comprimento total, alturas das pontas e
  // banzo superior -- e nada da corrente das verticais.
  if (!fs.existsSync(path.join(FIX_LEITOR, 'caso4.dxf')) || !fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, path.join(FIX_LEITOR, 'caso4.dxf'), { viewport: { width: 1400, height: 900 } });
  const mv = await pg.evaluate(() => window.__leitorTeste.marcasVerticais ? window.__leitorTeste.marcasVerticais() : { erro: 'sem gancho' }).catch(e => ({ erro: e.message }));
  const m0 = Array.isArray(mv) ? mv[0] : null, JM = JSON.stringify(mv).slice(0, 1200);
  t.ok('a corrente começa na cumeeira e vai para os dois lados', !!m0 && m0.lados.length === 2 &&
    m0.lados.every(l => l.marcas.every((q, i) => !i || (l.lado < 0 ? q.x < l.marcas[i - 1].x : q.x > l.marcas[i - 1].x))), JM);
  t.ok('mede pela aba interna: face esquerda do lado esquerdo, face direita do lado direito', !!m0 &&
    m0.lados.every(l => l.marcas.filter(q => q.pos).every(q => Math.abs(q.x - (l.lado < 0 ? q.mn : q.mx)) < 0.01)), JM);
  const mm = await leitorPranchasCotas(pg, false), J = JSON.stringify(mm).slice(0, 1800) + ' ' + erros.join(' | ');
  const trechos = mm.filter(x => /TRECHO/.test(x.tit || '')), completas = mm.filter(x => /COMPLETA/.test(x.tit || ''));
  // "deveria aparecer a cota azul da distância de vão na folha inteira":
  // a folha da tesoura completa leva as medidas gerais E a corrente toda
  t.ok('folha completa: comprimento total, banzo superior e a corrente das verticais inteira', completas.length > 0 &&
    completas.every(x => x.ps.length >= 10 && x.inicio > 0 && !x.ref.length && x.gerais.some(g => /comprimento total/.test(g)) && x.gerais.some(g => /banzo superior/.test(g)) && x.alturas >= 2), J);
  t.ok('cada trecho: P das verticais e uma cota entre cada duas, sem medidas gerais', trechos.length >= 2 &&
    trechos.every(x => x.ps.length >= 2 && x.cotas.length >= x.ps.length - 1 && !x.gerais.length), J);
  t.ok('o trecho sem a cumeeira diz a que distância dela começa; o da cumeeira marca o início', trechos.filter(x => !x.inicio).every(x => x.ref.length >= 1 &&
    x.ref.every(r => /^P\d+ a [\d.]+ mm da P\d+ \((cumeeira|ponta alta)\)$/.test(r))) && trechos.some(x => x.inicio > 0), J);
  t.ok('a frase antiga "do início da tesoura" saiu', mm.every(x => !(x.ref || []).some(r => /início da tesoura/.test(r))), J);
  const cm = await leitorPranchasCotas(pg, true), J2 = JSON.stringify(cm.map(x => x.cotas)).slice(0, 800);
  const nmm = v => +v.replace(/\./g, ''), ncm = v => parseFloat(v.replace(/\./g, '').replace(',', '.'));
  // em cm a letra é mais larga e a tesoura pode partir em outro número de
  // trechos: confere cada cota em cm contra as medidas que existem em mm
  const todasMM = mm.flatMap(x => x.cotas.map(nmm));
  t.ok('"Ver em cm" muda a cota também', cm.some(x => x.cotas.length) && cm.every(x => x.cotas.every(c => /,\d$/.test(c) &&
    todasMM.some(v => Math.abs(ncm(c) * 10 - v) < 0.51))), J2);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-prancha-cota-suporte-terca', async (b, t) => {
  // A cota da arquiteta ao longo do banzo de cima marca onde cada suporte de
  // terça é soldado. O leitor acha essa cota pela posição (encostada e
  // paralela ao banzo superior), sem camada especial, e põe na prancha em
  // laranja com um triângulo em cada suporte. Uma cota no banzo de baixo e
  // uma cota solta longe da tesoura NÃO entram.
  const ex = path.join(RAIZ, 'leitor_dwg', 'modelo', 'RM_EXEMPLO.dxf');
  if (!fs.existsSync(ex)) return;
  const ysup = x => 40 + (x <= 600 ? x : 1200 - x) * 110 / 600;   // o mesmo desenho do gera_modelo.py (cm)
  const dim = (a, b, v) => ['0', 'DIMENSION', '8', 'RM-COTA', '13', a[0], '23', a[1], '14', b[0], '24', b[1], '42', v].join('\n') + '\n';
  let ents = '';
  // a arquiteta cota pela linha de cada vertical do projeto, de ponta a ponta
  for (const [x0, x1] of [[0, 200], [200, 400], [400, 600], [600, 800], [800, 1000], [1000, 1200]])
    ents += dim([x0, ysup(x0)], [x1, ysup(x1)], Math.hypot(x1 - x0, ysup(x1) - ysup(x0)));
  ents += dim([0, 0], [1200, 0], 1200);            // banzo de baixo: não é suporte de terça
  ents += dim([3000, 3000], [3200, 3036.67], 203);  // solta, longe da tesoura
  const txt = fs.readFileSync(ex, 'latin1').replace(/(\n\s*2\s*\nENTITIES\s*\n)/, '$1' + ents);
  const arq = path.join(require('os').tmpdir(), 'rm_exemplo_cota_terca.dxf'); fs.writeFileSync(arq, txt, 'latin1');
  const { ctx, pg, erros } = await leitorImporta(b, arq, { viewport: { width: 1400, height: 900 } });
  const r = await leitorPranchasCotas(pg, false), J = JSON.stringify(r).slice(0, 1500) + ' ' + erros.join(' | ');
  if (process.env.PRANCHA_DOC) fs.writeFileSync(process.env.PRANCHA_DOC.replace(/\.html$/, '-terca.html'), await pg.evaluate(() => window.__docPrancha || ''));
  const todas = r.flatMap(x => x.laranja || []);
  t.ok('as seis cotas do banzo de cima saem em laranja, com o número do DWG (2.033 mm)', r.some(x => (x.laranja || []).length === 6) && todas.every(v => v === '2.033'), J);
  const ct = await pg.evaluate(() => window.__leitorTeste.cotaTerca ? window.__leitorTeste.cotaTerca() : { erro: 'sem gancho' }).catch(e => ({ erro: e.message }));
  const xs = Array.isArray(ct) && ct[0] ? ct[0].map(q => Math.round(q.x)) : [];
  // duas águas: a vertical da cumeeira está centrada no meio -- todo ▲ fica
  // onde a arquiteta pôs, inclusive nas pontas baixas
  t.ok('cada ▲ no ponto do DWG (0, 2.000 ... 12.000 mm)', JSON.stringify(xs) === JSON.stringify([0, 2000, 4000, 6000, 8000, 10000, 12000]), JSON.stringify(ct));
  t.ok('um triângulo em cada suporte (sete pontos)', r.some(x => x.triangulos === 7), J);
  t.ok('a cota do banzo de baixo e a solta ficam de fora', !todas.some(v => /12\.000|2\.030/.test(v)), J);
  // "coloca a cota azul também na folha única": a tesoura que não foi partida
  // leva as medidas gerais E a corrente das verticais a partir da cumeeira
  const unica = r.find(x => !/TRECHO|COMPLETA/.test(x.tit || ''));
  t.ok('folha única: corrente azul das verticais (as 7) com o início na cumeeira, mais o comprimento total', !!unica && unica.ps.length === 7 &&
    unica.inicio > 0 && unica.gerais.some(g => /comprimento total/.test(g)), JSON.stringify(unica));
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-prancha-cota-suporte-cumeeira', async (b, t) => {
  // Meia tesoura: a cumeeira é a ponta alta. A arquiteta cota até a linha da
  // ponta, mas a vertical da cumeeira vira um perfil encostado na ponta e o
  // suporte é soldado no eixo dele: só esse ▲ vai para dentro. O NÚMERO
  // continua o dela ("1,33 não está no dwg e nem 1,47").
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const ysup = x => 20 + 150 * x / 1200, L = [];
  const ln = (x1, y1, x2, y2, cor, lay) => L.push([x1, y1, x2, y2, cor, lay || '0']);
  ln(0, 0, 1200, 0, 2); ln(0, 20, 1200, 170, 2);
  const xs0 = [0, 200, 400, 600, 800, 1000, 1200];
  xs0.forEach(x => ln(x, 0, x, ysup(x), 1));
  for (let k = 0; k < 6; k++) ln(xs0[k], ysup(xs0[k]), xs0[k + 1], 0, 1);
  [[-50, -60, 1250, -60], [1250, -60, 1250, 260], [1250, 260, -50, 260], [-50, 260, -50, -60]].forEach(q => L.push([...q, 3, 'QUADRO']));
  const f = dxfTeste('meia_tesoura_cota', L, [['TESOURA 01\\PU 40x100x40 #2,00\\PU 30x93x30 #2,00\\PQTD: 2', 100, 240]]);
  const dim = (a, c, v) => ['0', 'DIMENSION', '8', 'COTA', '13', a[0], '23', a[1], '14', c[0], '24', c[1], '42', v].join('\n') + '\n';
  let ents = '';
  for (let k = 0; k < 6; k++) ents += dim([xs0[k], ysup(xs0[k])], [xs0[k + 1], ysup(xs0[k + 1])], Math.hypot(200, ysup(xs0[k + 1]) - ysup(xs0[k])));
  fs.writeFileSync(f, fs.readFileSync(f, 'latin1').replace(/(\n2\nENTITIES\n)/, '$1' + ents), 'latin1');
  const { ctx, pg, erros } = await leitorImporta(b, f, { viewport: { width: 1400, height: 900 } });
  const r = await leitorPranchasCotas(pg, false), J = JSON.stringify(r).slice(0, 1200) + ' ' + erros.join(' | ');
  if (process.env.PRANCHA_DOC) fs.writeFileSync(process.env.PRANCHA_DOC.replace(/\.html$/, '-meia.html'), await pg.evaluate(() => window.__docPrancha || ''));
  const todas = r.flatMap(x => x.laranja || []);
  t.ok('os números são os do DWG (2.015 mm cada), sem 1,33 nem 1,47', todas.length >= 6 && todas.every(v => v === '2.015'), J);
  const ct = await pg.evaluate(() => window.__leitorTeste.cotaTerca()).catch(e => ({ erro: e.message }));
  const mv = await pg.evaluate(() => window.__leitorTeste.marcasVerticais()).catch(e => ({ erro: e.message }));
  const pts = Array.isArray(ct) && ct[0] ? ct[0] : [], ult = pts[pts.length - 1] || {};
  const vC = Array.isArray(mv) && mv[0] ? mv[0].lados.flatMap(l => l.marcas).find(q => q.pos && q.mx >= 11999) : null;
  t.ok('só o ▲ da cumeeira vai para o eixo da vertical dela; os outros ficam no ponto do DWG', pts.length === 7 && !!vC &&
    Math.abs(ult.x - (vC.mn + vC.mx) / 2) < 0.5 && ult.x < 12000 && Math.round(ult.xDwg) === 12000 &&
    pts.slice(0, 6).every((q, k) => Math.round(q.x) === xs0[k] * 10), JSON.stringify({ pts, vC }));
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-tres-pedidos', async (b, t) => {
  // "Cada campo desses deveria ter um botão próprio: Compra - pedido de barras
  // de 6 metros; Detalhamento - pedido todo detalhado; Chapas + parceiros -
  // pedido detalhado com os códigos, porém com quantas chapas de cada largura".
  if (!fs.existsSync(path.join(FIX_LEITOR, 'caso4.dxf')) || !fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, path.join(FIX_LEITOR, 'caso4.dxf'), { viewport: { width: 1400, height: 900 } });
  const r = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms));
    window.confirm = () => true;
    const grupo = id => { const bt = document.getElementById(id); const g = bt && bt.closest('.saida'); return g ? g.querySelector('.saida-t').textContent : null; };
    const o = { grupos: { barras: grupo('lfBarras'), det: grupo('listaForn'), chapas: grupo('lfChapas') } };
    const pa = () => document.getElementById('printArea');
    document.getElementById('lfBarras').click(); await esp(400);
    o.barras = { tag: (pa().querySelector('.tb2-tipo') || {}).textContent, linhas: [...pa().querySelectorAll('table.lf-barras tbody tr')].map(tr => [...tr.cells].map(c => c.textContent.trim())),
      opc: !!document.getElementById('lfBanzos') };
    document.getElementById('lfClose').click();
    document.getElementById('detalhar').click(); await esp(300);
    document.getElementById('listaForn').click(); await esp(400);
    o.det = { tag: (pa().querySelector('.tb2-tipo') || {}).textContent, fam: pa().querySelectorAll('.lf-fam').length, chapas: !!pa().querySelector('.lf-chapas') };
    document.getElementById('lfClose').click();
    document.getElementById('lfChapas').click(); await esp(600);
    const ch = pa().querySelector('.lf-chapas');
    o.chapas = { tag: (pa().querySelector('.tb2-tipo') || {}).textContent, fam: pa().querySelectorAll('.lf-fam').length,
      linhas: ch ? [...ch.querySelectorAll('tbody tr')].map(tr => [...tr.cells].map(c => c.textContent.trim())) : null };
    const L = window.__leitorTeste; o.plano = L.chapas().sheets.map(x => x.w);
    o.compraBarras = null;
    return o;
  }).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r).slice(0, 1800) + ' ' + erros.join(' | ');
  const n = v => +String(v).replace(/\./g, '');
  t.ok('um botão em cada grupo: Compra (barras), Fábrica (detalhado), Laser (chapas)', !r.erro && /Compra/i.test(r.grupos.barras) && /Fábrica/i.test(r.grupos.det) && /Laser/i.test(r.grupos.chapas), J);
  t.ok('pedido de barras: perfil, uso, barras e metros, sem a opção de banzos (já vão inteiros)', !r.erro && /Barras de 6\.000 mm/.test(r.barras.tag) && r.barras.linhas.length > 0 &&
    r.barras.linhas.some(l => /Banzo/.test(l[1])) && r.barras.linhas.every(l => n(l[2]) > 0 && Math.abs(n(l[3]) - n(l[2]) * 6) <= 1) && !r.barras.opc, J);
  t.ok('pedido detalhado: as famílias peça a peça, sem a tabela de chapas', !r.erro && /Peças cortadas/.test(r.det.tag) && r.det.fam > 0 && !r.det.chapas, J);
  const tot = (r.chapas && r.chapas.linhas || []).reduce((s, l) => s + n(l[3]), 0);
  const porW = {}; (r.plano || []).forEach(w => porW[w] = (porW[w] || 0) + 1);
  t.ok('pedido chapas + parceiro: o detalhado mais quantas chapas de cada largura (igual ao plano)', !r.erro && /Chapas \+ parceiro/.test(r.chapas.tag) && r.chapas.fam === r.det.fam &&
    tot === (r.plano || []).length && Object.entries(porW).every(([w, q]) => r.chapas.linhas.some(l => n(l[2].split(' × ')[0]) === +w && n(l[3]) >= 1)), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-pedido-fabricante-sem-folha-branca-e-banzos', async (b, t) => {
  // "O pedido para o fabricante está gerando espaçamento em branco" e "coloque
  // uma opção de incluir os perfil banzos (superior e inferior)". Cada família
  // era um bloco flex de várias tabelas, que o navegador não parte: quando não
  // cabia no resto da folha, pulava inteira e deixava a folha em branco.
  if (!fs.existsSync(path.join(FIX_LEITOR, 'caso1.dxf')) || !fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, path.join(FIX_LEITOR, 'caso1.dxf'), { viewport: { width: 1400, height: 900 } });
  const gera = bz => pg.evaluate(async (bz) => {
    let h = null; window.rmDesktop = { salvarPDF: async (x) => { h = x; return { ok: true }; } }; window.confirm = () => true;
    document.getElementById('detalhar').click(); await new Promise(x => setTimeout(x, 300));
    document.getElementById('listaForn').click(); await new Promise(x => setTimeout(x, 500));
    const cb = document.getElementById('lfBanzos'); if (!cb) return { erro: 'sem a opção dos banzos' };
    if (cb.checked !== bz) cb.click(); await new Promise(x => setTimeout(x, 300));
    const famh = [...document.querySelectorAll('#printArea .lf-famh')].map(x => x.firstChild.textContent.trim());
    const tabs = [...document.querySelectorAll('#printArea .lf-cols')].map(c => c.querySelectorAll('table').length);
    const banzoP = [...document.querySelectorAll('#printArea .lf-cod')].filter(x => /banzo/.test(x.textContent)).length;
    const desenhos = document.querySelectorAll('#printArea .prancha, #printArea .lf-desenhos').length;
    const notas = /Comprimentos em milímetro inteiro|Cada peça deve chegar marcada|Peso estimado pelo kg\/m/.test(document.getElementById('printArea').textContent);
    document.getElementById('lfPrint').click(); await new Promise(x => setTimeout(x, 900));
    return { h, famh, tabs, banzoP, desenhos, notas, guardou: localStorage.getItem('rm_lf_banzos') };
  }, bz).catch(e => ({ erro: e.message }));
  const paginas = async h => { const p = await ctx.newPage(); await p.setContent((h || '').replace('</head>', '<style>#printArea .lf-desenhos{display:none!important}</style></head>'));
    const pdf = await p.pdf({ preferCSSPageSize: true, printBackground: true }).catch(() => null); await p.close();
    return pdf ? (pdf.toString('latin1').match(/\/Type\s*\/Page[^s]/g) || []).length : 0; };
  const sem = await gera(false); sem.paginas = await paginas(sem.h); delete sem.h;
  const J = JSON.stringify(sem) + ' ' + erros.join(' | ');
  t.ok('cada família é uma tabela só (parte entre páginas linha a linha)', !sem.erro && sem.tabs.length > 0 && sem.tabs.every(n => n === 1), J);
  t.ok('as tabelas do pedido cabem em 4 folhas (antes 6, com folhas em branco)', !sem.erro && sem.paginas > 0 && sem.paginas <= 4, J);
  t.ok('sem a opção: nenhum banzo no pedido', !sem.erro && !sem.famh.some(f => /banzo/i.test(f)) && sem.banzoP === 0, J);
  // "só preciso que saia a lista de compras, não precisa sair a montagem e o desenho separado"
  t.ok('o pedido leva só a lista: sem prancha de montagem nem folha por grupo', !sem.erro && sem.desenhos === 0, J);
  // "Essa informação não precisa sair no pedido para o fornecedor": sem o quadro de notas de oficina
  t.ok('o pedido sai sem o quadro de notas (milímetro, folga, marcação, peso estimado)', !sem.erro && sem.notas === false, J);
  const com = await gera(true); com.paginas = await paginas(com.h); delete com.h;
  const J2 = JSON.stringify(com);
  t.ok('com a opção: famílias Banzo superior e Banzo inferior, com a linha de banzo na coluna P', !com.erro &&
    com.famh.some(f => /^Banzo superior$/i.test(f)) && com.famh.some(f => /^Banzo inferior$/i.test(f)) && com.banzoP > 0 && com.guardou === '1', J2);
  t.ok('com banzos também sem folha em branco (cabe em 6)', !com.erro && com.paginas > 0 && com.paginas <= 6, J2);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-prancha-emenda-banzo', async (b, t) => {
  // "Nos banzo ao definir junto preciso ver como o sistema está dividindo,
  // precisa estar na lista do montador": a prancha marca cada emenda no
  // banzo e numera os pedaços (BS 1/2 · 6.000), os mesmos do pedido.
  if (!fs.existsSync(path.join(FIX_LEITOR, 'caso4.dxf')) || !fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, path.join(FIX_LEITOR, 'caso4.dxf'), { viewport: { width: 1400, height: 900 } });
  const r = await pg.evaluate(async () => {
    window.rmDesktop = { salvarPDF: async () => ({ ok: true }) }; window.confirm = () => true;
    document.getElementById('detalhar').click(); await new Promise(x => setTimeout(x, 300));
    document.getElementById('dtPrancha').click(); await new Promise(x => setTimeout(x, 900));
    const folhas = [...document.querySelectorAll('#dtPranchas .prancha')].map(pr => {
      const tx = [...pr.querySelectorAll('svg text[fill="#7b3fb5"]')];
      return { tit: pr.querySelector('svg > text').textContent, pedacos: tx.map(x => x.textContent), ys: tx.map(x => +x.getAttribute('y')).map(Math.round),
        setas: pr.querySelectorAll('svg path[fill="#7b3fb5"]').length, marcas: pr.querySelectorAll('svg line[stroke="#7b3fb5"]').length };
    });
    // o mesmo plano do pedido: os pedaços de banzo da lista do fornecedor
    document.getElementById('listaForn').click(); await new Promise(x => setTimeout(x, 400));
    const cb = document.getElementById('lfBanzos'); if (cb && !cb.checked) cb.click(); await new Promise(x => setTimeout(x, 300));
    const pedido = [...document.querySelectorAll('#printArea .lf-fam')].filter(f => /banzo/i.test(f.querySelector('.lf-famh').textContent))
      .flatMap(f => [...f.querySelectorAll('.lf-len')].map(x => x.textContent));
    if (cb && cb.checked) cb.click();
    return { folhas, pedido };
  }).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r).slice(0, 1500) + ' ' + erros.join(' | ');
  const comp = (r.folhas || []).find(f => /COMPLETA/.test(f.tit)) || {};
  // "A informação do recorte dos banzos está deslocada, organize de forma
  // alinhada e com setas direcionando": uma etiqueta por emenda, numa fileira
  // (mesma altura no papel para o superior, outra para o inferior), com seta
  // (a emenda ganhou número: "E1 · EMENDA BS · ...", o mesmo do quadro da folha longa)
  const re = /^E\d+ · EMENDA (B[SI]) · (\d+)\/(\d+) ([\d.]+)  \|  (\d+)\/(\d+) ([\d.]+)$/;
  const et = (comp.pedacos || []).map(x => x.match(re));
  const bs = (comp.pedacos || []).map((x, i) => [x, comp.ys[i]]).filter(([x]) => /^E\d+ · EMENDA BS/.test(x)), bi = (comp.pedacos || []).map((x, i) => [x, comp.ys[i]]).filter(([x]) => /^E\d+ · EMENDA BI/.test(x));
  t.ok('uma etiqueta por emenda, com seta e marca no banzo', et.length >= 2 && et.every(Boolean) && comp.setas === et.length && comp.marcas >= et.length, J);
  t.ok('etiquetas alinhadas: todas do superior numa altura, todas do inferior em outra', bs.length >= 1 && bi.length >= 1 &&
    new Set(bs.map(x => x[1])).size === 1 && new Set(bi.map(x => x[1])).size === 1 && bs[0][1] !== bi[0][1], J);
  // cada banzo superior de 8.685 sai em 6.000 + 2.685 (o plano da barra de 6 m)
  t.ok('os pedaços de cada emenda somam o banzo (8.685) e estão no pedido com banzos', et.filter(m => m && m[1] === 'BS').every(m => Math.abs(+m[4].replace(/\./g, '') + +m[7].replace(/\./g, '') - 8685) <= 2) &&
    et.every(m => m && (r.pedido || []).includes(m[4]) && (r.pedido || []).includes(m[7])), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

/* ---- Auditoria da aba Detalhamento do Leitor DWG ----
   "Análise o leitor dwg - aba detalhamento / PDF gerados ... encontre erros,
   proponha melhorias" -> "pode aplicar tudo, pedaço curto na ponta baixa;
   o parceiro cobra pelo peso da peça pronta; A3 automático: sim". */
const LEITOR_EXEMPLO = () => path.join(RAIZ, 'leitor_dwg', 'modelo', 'RM_EXEMPLO.dxf');
/* PDF de um documento de impressão capturado: páginas e tamanho de cada uma */
async function leitorPdfInfo(ctx, h) {
  const p = await ctx.newPage();
  await p.setContent(h || '<p>sem documento</p>');
  const pdf = await p.pdf({ preferCSSPageSize: true, printBackground: true }).catch(() => null);
  await p.close();
  if (!pdf) return { n: 0, tam: [] };
  const s = pdf.toString('latin1');
  const tam = [...s.matchAll(/\/MediaBox\s*\[\s*0 0 ([\d.]+) ([\d.]+)\s*\]/g)].map(m => Math.round(+m[1]) + 'x' + Math.round(+m[2]));
  return { n: (s.match(/\/Type\s*\/Page[^s]/g) || []).length, tam };
}
/* clica no botão da aba Detalhamento e devolve o HTML mandado para o PDF */
const leitorCapturaPdf = (pg, botao, cm) => pg.evaluate(async ({ botao, cm }) => {
  const esp = ms => new Promise(x => setTimeout(x, ms));
  let h = null; window.rmDesktop = { salvarPDF: async x => { h = x; return { ok: true }; } }; window.confirm = () => true;
  if (!document.getElementById(botao)) { document.getElementById('detalhar').click(); await esp(400); }
  if (cm && /cm/.test(document.getElementById('dtUnid').textContent)) { document.getElementById('dtUnid').click(); await esp(300); }
  document.getElementById(botao).click(); await esp(1500);
  const folhas = [...document.querySelectorAll('#dtPranchas .prancha')].map(pr => ({
    folha: pr.dataset.folha || '', tit: (pr.querySelector('svg > text') || {}).textContent || '',
    txt: [...pr.querySelectorAll('svg text')].map(x => ({ t: x.textContent, x: +x.getAttribute('x'), y: +x.getAttribute('y'),
      f: x.getAttribute('fill'), fs: +x.getAttribute('font-size'), a: x.getAttribute('text-anchor') })) }));
  return { h, folhas };
}, { botao, cm: !!cm }).catch(e => ({ erro: e.message }));

teste('leitor-emenda-ponta-baixa', async (b, t) => {
  // Auditoria: as duas águas da tesoura de 12 m eram cortadas ao contrário
  // (o pedaço curto na cumeeira numa e na ponta baixa na outra) e a emenda do
  // banzo de baixo caía no nó da cumeeira sem nenhum destaque. Regra do
  // Everton: "pedaço curto na ponta baixa".
  if (!fs.existsSync(LEITOR_EXEMPLO())) return;
  const { ctx, pg, erros } = await leitorImporta(b, LEITOR_EXEMPLO(), { viewport: { width: 1400, height: 900 } });
  const r = await leitorCapturaPdf(pg, 'dtPrancha');
  const f = (r.folhas || [])[0] || { txt: [] };
  const em = f.txt.filter(x => /EMENDA/.test(x.t)).sort((p, q) => p.x - q.x);
  const bs = em.filter(x => /EMENDA BS/.test(x.t)), bi = em.filter(x => /EMENDA BI/.test(x.t));
  const pedacos = x => (x.t.match(/(\d+)\/\d+ ([\d.]+)/g) || []).map(s => +s.split(' ')[1].replace(/\./g, ''));
  const rel = await pg.evaluate(async () => { document.getElementById('dtPrint').click(); await new Promise(x => setTimeout(x, 300));
    return [...document.querySelectorAll('#printArea .rc-t')].filter(tb => /Pedaços \(emenda\)/.test(tb.innerText))
      .map(tb => tb.innerText.replace(/\s+/g, ' ')).join(' || '); }).catch(e => 'erro ' + e.message);
  const J = JSON.stringify({ erro: r.erro, em: em.map(x => [x.t, x.f, Math.round(x.x)]), rel: String(rel).slice(0, 500) }) + ' ' + erros.join(' | ');
  t.ok('as duas águas cortam igual: o pedaço curto (500) fica na ponta baixa de cada lado', !r.erro && bs.length === 2 &&
    pedacos(bs[0])[0] === 500 && pedacos(bs[0])[1] === 5600 && pedacos(bs[1])[0] === 5600 && pedacos(bs[1])[1] === 500, J);
  t.ok('emendas numeradas da esquerda para a direita (E1 à esquerda, E2 à direita)', bs.length === 2 && /^E1 · /.test(bs[0].t) && /^E2 · /.test(bs[1].t), J);
  t.ok('a emenda do banzo de baixo em cima do nó sai em vermelho, escrito SOBRE NÓ', bi.length === 1 && bi[0].f === '#c0262d' && /SOBRE NÓ/.test(bi[0].t), J);
  t.ok('no relatório as duas águas viram uma linha só (mesmo plano), e o nó diz de que ponta', /Superior[^|]*?2[^|]*?5\.600 mm \+ 500 mm/.test(rel) && /emenda sobre nó a [\d.]+ mm da ponta/.test(rel), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-trelica-corrente-p1', async (b, t) => {
  // Auditoria: na treliça de banzos paralelos não existe ponta alta, e a
  // corrente azul começava numa ponta qualquer ("P21 a 49.985 mm da P121
  // (ponta alta)"). Banzo de cima deitado começa na ponta esquerda, em P1.
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const L = [];
  const ln = (x1, y1, x2, y2, cor, lay) => L.push([x1, y1, x2, y2, cor, lay || '0']);
  ln(0, 0, 1200, 0, 2); ln(1200, 80, 0, 80, 2);                 // o banzo de cima desenhado da direita para a esquerda
  for (const x of [0, 200, 400, 600, 800, 1000, 1200]) ln(x, 0, x, 80, 1);
  for (let x = 0; x < 1200; x += 200) ln(x, 80, x + 200, 0, 1);
  [[-50, -60], [1250, -60], [1250, 200], [-50, 200]].forEach((q, i, a) => ln(q[0], q[1], a[(i + 1) % 4][0], a[(i + 1) % 4][1], 3, 'QUADRO'));
  const arq = dxfTeste('trelica_p1', L, [['TRELIÇA 01\\PU 40x100x40 #2,00\\PU 30x93x30 #2,00\\PQTD: 2', 100, 160]]);
  const { ctx, pg, erros } = await leitorImporta(b, arq);
  const r = await pg.evaluate(() => (window.__leitorTeste.marcasVerticais() || [])[0]).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r) + ' ' + erros.join(' | ');
  t.ok('a corrente começa em P1, na ponta esquerda', r && !r.erro && r.inicio === 'P1' && r.lados.length === 1 && r.lados[0].lado === 1 && r.lados[0].marcas[0].pos === 'P1', J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-prancha-completa-legivel', async (b, t) => {
  // Auditoria: a folha da tesoura de 41 m numa A4 saía com letra de 1,7 mm,
  // as etiquetas das emendas uma em cima da outra e os números da corrente
  // azul encavalados nas pontas. "A3 automático: sim".
  if (!fs.existsSync(path.join(FIX_LEITOR, 'caso1.dxf')) || !fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, path.join(FIX_LEITOR, 'caso1.dxf'), { viewport: { width: 1400, height: 900 } });
  const r = await leitorCapturaPdf(pg, 'dtPrancha');
  const pdf = r.h ? await leitorPdfInfo(ctx, r.h) : { n: 0, tam: [] };
  const comp = (r.folhas || []).find(f => /Estrutura A/.test(f.tit) && /COMPLETA/.test(f.tit)) || { txt: [] };
  const letra = +((comp.txt.find(x => /letra [\d,]+ mm/.test(x.t)) || { t: '' }).t.match(/letra ([\d,]+) mm/) || [0, '0'])[1].replace(',', '.');
  const roxo = comp.txt.filter(x => x.f === '#7b3fb5' || x.f === '#c0262d');
  const marcas = roxo.filter(x => /^E\d+$/.test(x.t)), quadro = comp.txt.filter(x => /^E\d+ · EMENDA B[SI]/.test(x.t));
  // números da corrente azul (sem negrito, "1.346"): na mesma fileira, nenhum encosta no vizinho
  const az = comp.txt.filter(x => x.f === '#1d4f91' && /^[\d.]+$/.test(x.t) && x.a === 'middle');
  const filas = {}; az.forEach(x => (filas[Math.round(x.y * 10)] = filas[Math.round(x.y * 10)] || []).push(x));
  let encosta = 0;
  Object.values(filas).forEach(l => { l.sort((p, q) => p.x - q.x); for (let i = 1; i < l.length; i++)
    if (l[i].x - l[i - 1].x < (l[i].t.length + l[i - 1].t.length) * l[i].fs * .6 / 2) encosta++; });
  const J = JSON.stringify({ erro: r.erro, folha: comp.folha, letra, pdf, marcas: marcas.length, quadro: quadro.length, encosta, filas: Object.keys(filas).length }) + ' ' + erros.join(' | ');
  t.ok('a folha da tesoura completa longa sai em A3, com letra acima de 2,2 mm', !r.erro && comp.folha === 'A3' && letra >= 2.2, J);
  t.ok('o PDF vai todo em A3 e sem folha em branco (uma página por prancha)', pdf.n === (r.folhas || []).length && pdf.tam.length === pdf.n && pdf.tam.every(x => x === '1191x842'), J);
  t.ok('as emendas viram E1, E2... no desenho e o quadro no pé da folha diz cada uma', marcas.length >= 6 && quadro.length === marcas.length, J);
  t.ok('os números da corrente azul não se encavalam (os apertados sobem um andar)', az.length > 20 && encosta === 0 && Object.keys(filas).length >= 2, J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-grupos-sem-folha-branca', async (b, t) => {
  // Auditoria: o PDF "Peças por grupo" sempre começava com uma folha em
  // branco -- a fileira de botões ficava no fluxo do papel com altura zero.
  if (!fs.existsSync(LEITOR_EXEMPLO())) return;
  const { ctx, pg, erros } = await leitorImporta(b, LEITOR_EXEMPLO(), { viewport: { width: 1400, height: 900 } });
  await leitorCapturaPdf(pg, 'dtPrancha');            // o caminho de quem usa: a prancha, depois os grupos
  const r = await leitorCapturaPdf(pg, 'dtGrupos');
  const pdf = r.h ? await leitorPdfInfo(ctx, r.h) : { n: 0 };
  const J = JSON.stringify({ erro: r.erro, n: (r.folhas || []).length, pdf }) + ' ' + erros.join(' | ');
  t.ok('uma página por estrutura, sem folha em branco', !r.erro && (r.folhas || []).length === 1 && pdf.n === 1, J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-dxf-montagem-cotas', async (b, t) => {
  // Auditoria: o DXF da montagem não dizia a unidade (num desenho em cm
  // entrava 10 vezes maior) e não tinha nenhuma das cotas novas da prancha.
  if (!fs.existsSync(LEITOR_EXEMPLO())) return;
  const { ctx, pg, erros } = await leitorImporta(b, LEITOR_EXEMPLO(), { viewport: { width: 1400, height: 900 } });
  const dxf = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms)); window.confirm = () => true;
    let txt = ''; const oc = URL.createObjectURL; URL.createObjectURL = bl => { bl.text().then(x => { txt = x; }); return oc.call(URL, bl); };
    document.getElementById('detalhar').click(); await esp(400);
    document.getElementById('dtDxf').click(); await esp(800);
    return txt; }).catch(e => 'erro ' + e.message);
  const camada = n => new RegExp('\\n8\\n' + n + '\\n').test(dxf);
  const J = String(dxf).slice(0, 300) + ' ' + erros.join(' | ');
  t.ok('o arquivo declara milímetro ($INSUNITS = 4)', /\$INSUNITS\n70\n4\n/.test(dxf), J);
  t.ok('leva a corrente azul, o comprimento total e as emendas, cada um na sua camada', camada('RM-COTA-VAO') && camada('RM-EMENDA') && camada('RM-EMENDA-NO') &&
    /12\.000 comprimento total/.test(dxf) && /E1 \\U\+00B7 EMENDA BS/.test(dxf) && /SOBRE N\\U\+00D3/.test(dxf), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-numero-na-peca', async (b, t) => {
  // "Facilitar a orientação" das setas: o montador tinha de seguir uma linha
  // fina até o fim, e numa tesoura longa dezenas correm lado a lado. Agora o
  // número da posição vai na própria peça (círculo), e o P da etiqueta sai em
  // negrito para bater com ele -- em todas as folhas, a da tesoura completa
  // inclusive. O DXF leva o mesmo círculo, na camada RM-POSICAO.
  if (!fs.existsSync(LEITOR_EXEMPLO())) return;
  const prancha = async arq => {
    const { ctx, pg, erros } = await leitorImporta(b, arq, { viewport: { width: 1400, height: 900 } });
    const r = await pg.evaluate(async () => {
      const esp = ms => new Promise(x => setTimeout(x, ms));
      let h = '', txt = ''; window.rmDesktop = { salvarPDF: async x => { h = x; return { ok: true }; } }; window.confirm = () => true;
      const oc = URL.createObjectURL; URL.createObjectURL = bl => { bl.text().then(x => { txt = x; }); return oc.call(URL, bl); };
      document.getElementById('detalhar').click(); await esp(400);
      document.getElementById('dtPrancha').click(); await esp(1500);
      document.body.classList.remove('so-prancha');
      document.getElementById('detalhar').click(); await esp(400);
      document.getElementById('dtDxf').click(); await esp(800);
      const d = new DOMParser().parseFromString(h, 'text/html');
      return [...d.querySelectorAll('.prancha svg')].map(sv => {
        const bal = [...sv.querySelectorAll('g.pos-peca')].map(g => { const c = g.querySelector('circle');
          return { n: g.textContent.trim(), x: +c.getAttribute('cx'), y: +c.getAttribute('cy'), r: +c.getAttribute('r') }; });
        const etiq = [...sv.querySelectorAll('text')].map(x => x.textContent).filter(x => /^[A-Z]+-P\d+-/.test(x));
        const negrito = [...sv.querySelectorAll('tspan[font-weight="800"]')].map(x => x.textContent);
        return { bal, etiq, negrito, linhas: sv.querySelectorAll('line[stroke="#78838e"]').length,
          regra: [...sv.querySelectorAll('text')].map(x => x.textContent).find(x => /POSIÇÃO P/.test(x)) || '' };
      }).concat([{ dxf: txt }]);
    }).catch(e => [{ erro: e.message }]);
    await ctx.close(); return { r, erros };
  };
  const sobrepoe = bal => bal.some((a, i) => bal.some((c, j) => j > i && Math.hypot(a.x - c.x, a.y - c.y) < a.r + c.r));
  // uma folha só (Tesoura 01 do exemplo, 13 posições)
  const ex = await prancha(LEITOR_EXEMPLO()), f = ex.r[0] || {}, dxf = (ex.r[ex.r.length - 1] || {}).dxf || '';
  const nums = (f.bal || []).map(x => x.n).sort((a, c) => a - c).join(' ');
  t.ok('cada peça tem o seu número, de 1 a 13', nums === Array.from({ length: 13 }, (_, i) => i + 1).join(' '), nums + ' ' + JSON.stringify(f).slice(0, 200));
  t.ok('o P de cada etiqueta sai em negrito e bate com o número da peça',
    (f.negrito || []).length === 13 && (f.negrito || []).every(p => (f.bal || []).some(x => 'P' + x.n === p)), JSON.stringify(f.negrito));
  t.ok('as setas continuam (para conferir)', f.linhas > 0 && (f.etiq || []).length === 13, f.linhas + ' / ' + (f.etiq || []).length);
  t.ok('nenhum número em cima de outro', f.bal && !sobrepoe(f.bal), '');
  t.ok('o cabeçalho explica o número', /O NÚMERO NA PEÇA É A POSIÇÃO P/.test(f.regra || ''), f.regra);
  const circ = (dxf.match(/\n0\nCIRCLE\n(?:[^\n]*\n){0,7}?8\nRM-POSICAO\n/g) || []).length;
  t.ok('o DXF leva os 13 círculos na camada RM-POSICAO', circ === 13, 'círculos: ' + circ);
  // tesoura longa: a folha completa e os trechos levam etiqueta, seta e número
  const lg = await prancha(path.join(FIX_LEITOR, 'caso1.dxf')), folhas = lg.r.slice(0, -1), fs0 = folhas[0] || {};
  t.ok('na folha da tesoura completa: etiquetas, setas e números', fs0.etiq && fs0.etiq.length > 40 && fs0.linhas > 0 && fs0.bal.length > 40 && !sobrepoe(fs0.bal),
    JSON.stringify({ e: (fs0.etiq || []).length, l: fs0.linhas, n: (fs0.bal || []).length }));
  t.ok('todo número da folha completa é a posição de uma etiqueta dela', (fs0.bal || []).every(x => fs0.negrito.includes('P' + x.n)), '');
  t.ok('todas as folhas levam etiqueta, seta e número, sem número em cima de outro', folhas.length >= 3 && folhas.every(x => x.etiq.length && x.linhas && x.bal.length && !sobrepoe(x.bal)),
    JSON.stringify(folhas.map(x => [x.etiq.length, x.bal.length])));
  t.ok('sem erro na página', !ex.erros.length && !lg.erros.length, ex.erros.concat(lg.erros).join(' | '));
});

teste('leitor-banzo-exato-no-detalhado', async (b, t) => {
  // Auditoria: no caminho detalhado o banzo continuava com 10% de quebra,
  // embora o plano de emenda já diga quantas barras se compram -- o mesmo
  // número da lista de compra. A quebra fica só no "tudo em barras".
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, trelicaTeste('banzo_exato'));
  const r = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms)), L = window.__leitorTeste;
    localStorage.setItem(L.cuKey, JSON.stringify({ barra: 300 })); L.chapasCfg({ sheetRkg: 7.5, serviceRkg: 4 });
    document.querySelector('[data-dsub="comp"]').click(); await esp(400);
    const cards = [...document.querySelectorAll('#detComp .cmp-card')].map(c => c.innerText.replace(/\s+/g, ' '));
    const lista = L.estado().LASTROWS.filter(x => /40X100X40/i.test(x.name.replace(/\s/g, ''))).map(x => x.bars);
    document.getElementById('cutReport').click(); await esp(500);
    return { cards, lista, rel: document.getElementById('printArea').innerText.replace(/\s+/g, ' ') };
  }).catch(e => ({ erro: e.message }));
  const n = c => +((String(c).match(/(\d+) barras de 6 m · (?:com quebra|plano de emenda)/) || [])[1]);
  const J = JSON.stringify({ erro: r.erro, cards: (r.cards || []).map(c => c.slice(0, 260)), lista: r.lista }) + ' ' + erros.join(' | ');
  t.ok('tudo em barras: banzo com a quebra; detalhado e chapas: barras do plano de emenda', !r.erro && /barras de 6 m · com quebra/.test(r.cards[0]) &&
    /barras de 6 m · plano de emenda/.test(r.cards[1]) && /barras de 6 m · plano de emenda/.test(r.cards[2]) && n(r.cards[0]) > 0, J);
  t.ok('o banzo do detalhado é o mesmo número da lista de compra', !r.erro && r.lista.length === 1 && n(r.cards[1]) === r.lista[0], J);
  t.ok('o relatório de corte diz "plano de emenda, sem quebra"', !r.erro && /plano de emenda, sem quebra/.test(r.rel), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-preco-obra-em-todas-as-telas', async (b, t) => {
  // Auditoria: o preço por kg digitado para a obra só valia nos cartões do
  // Comparativo; o relatório de corte e a tela de chapas seguiam com o banco
  // -- o mesmo caminho com dois valores.
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, trelicaTeste('preco_telas'));
  const r = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms)), L = window.__leitorTeste;
    localStorage.setItem(L.cuKey, JSON.stringify({ barra: 300 })); L.chapasCfg({ sheetRkg: 7.5, serviceRkg: 4 });
    document.querySelector('[data-dsub="comp"]').click(); await esp(400);
    const poe = async (k, v) => { const i = document.querySelector('#detComp [data-cmp-preco="' + k + '"]');
      i.value = v; i.dispatchEvent(new Event('change', { bubbles: true })); await esp(200); };
    await poe('barra', '5'); await poe('det', '4'); await poe('chapa', '3');
    const cards = L.comparativo().textos;
    document.getElementById('cutReport').click(); await esp(600);
    const rel = document.getElementById('printArea').innerText.replace(/\s+/g, ' ');
    await poe('barra', ''); await poe('det', ''); await poe('chapa', '');
    return { cards, rel };
  }).catch(e => ({ erro: e.message }));
  const nr = s => String(s || '').replace(/\s+/g, ' ');
  const sem = (nr(r.rel).match(/Custo: tudo em barras de 6 m (R\$ [\d.,]+)/) || [])[1];
  const ch = (nr(r.rel).match(/Chapas \+ parceiro \+ banzos (R\$ [\d.,]+)/) || [])[1];
  const J = JSON.stringify({ erro: r.erro, cards: r.cards, sem, ch, rel: nr(r.rel).slice(0, 200) }) + ' ' + erros.join(' | ');
  t.ok('relatório de corte: "tudo em barras" com o preço da obra, igual ao cartão', !r.erro && sem && nr(sem) === nr(r.cards[0]), J);
  t.ok('chapas + parceiro com o preço fixo da obra, igual ao cartão, e a linha que diz isso', !r.erro && ch && nr(ch) === nr(r.cards[2]) && /Preço desta obra: chapas \+ parceiro/.test(r.rel), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-parceiro-peso-peca-pronta', async (b, t) => {
  // "cobra pelo peso da peça pronta, diferente da Perfitec ou outro
  // fornecedor que cobra o aproveitamento (188,8 é cobrado 200 mm)": o
  // serviço do parceiro usava o kg/m do aproveitamento da bobina.
  if (!fs.existsSync(path.join(RAIZ, 'leitor_dwg'))) return;
  const { ctx, pg, erros } = await leitorImporta(b, trelicaTeste('peso_pronta'));
  const r = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms)), L = window.__leitorTeste;
    localStorage.setItem(L.cuKey, JSON.stringify({ barra: 300 })); L.chapasCfg({ sheetRkg: 7.5, serviceRkg: 4 });
    document.querySelector('[data-dsub="comp"]').click(); await esp(400);
    const s = (L.secoes().secoes || [])[0], sh = L.chapaPerfil('U 30X93X30 #2,00', 2, 'carbono');
    return { peso: L.comparativo().pesoChapa, mm: s.tot, flat: sh.flat,
      card: document.querySelectorAll('#detComp .cmp-card')[2].innerText.replace(/\s+/g, ' ') };
  }).catch(e => ({ erro: e.message }));
  const esperado = r.mm / 1000 * r.flat * 2 * 8000 / 1e6;
  const J = JSON.stringify({ ...r, esperado }) + ' ' + erros.join(' | ');
  t.ok('peso do serviço = comprimento das peças × largura aberta da tira × espessura × densidade', !r.erro && r.flat > 140 && r.flat < 150 && Math.abs(r.peso - esperado) < esperado * 0.005, J);
  t.ok('o cartão diz que é o peso das peças prontas', !r.erro && /kg das peças prontas/.test(r.card), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('leitor-codigo-unico-e-unidade', async (b, t) => {
  // Auditoria: em "Ver em cm" a prancha mudava os códigos, mas o relatório
  // e o localizador continuavam com o código do laser em mm ("Comp. (mm)") --
  // a mesma peça com dois nomes.
  if (!fs.existsSync(LEITOR_EXEMPLO())) return;
  const { ctx, pg, erros } = await leitorImporta(b, LEITOR_EXEMPLO(), { viewport: { width: 1400, height: 900 } });
  const r = await leitorCapturaPdf(pg, 'dtPrancha', true);
  const prancha = ((r.folhas || [])[0] || { txt: [] }).txt.filter(x => x.f === '#D53309' && /-P\d+-/.test(x.t)).map(x => x.t);
  const o = await pg.evaluate(async () => {
    document.body.classList.remove('so-prancha');
    document.getElementById('dtPrint').click(); await new Promise(x => setTimeout(x, 400));
    const rel = [...document.querySelectorAll('#printArea .rc-pos tbody tr')].map(tr => tr.lastElementChild.innerText.trim());
    const loc = document.querySelector('#printArea [aria-label="Posições do mapa de localização"] thead');
    return { rel, loc: loc ? loc.innerText : '', aviso: (document.getElementById('dxfAviso') || {}).innerText || '' };
  }).catch(e => ({ erro: e.message }));
  const J = JSON.stringify({ erro: r.erro || o.erro, prancha: prancha.slice(0, 4), rel: (o.rel || []).slice(0, 4), loc: o.loc, aviso: String(o.aviso).slice(0, 160) }) + ' ' + erros.join(' | ');
  t.ok('em cm, a identificação do relatório é o mesmo código da prancha', !r.erro && prancha.length > 5 && (o.rel || []).length === prancha.length &&
    o.rel.every(x => prancha.includes(x)) && o.rel.every(x => /CM$/.test(x)), J);
  t.ok('o aviso das pranchas fala em cm', /comprimento de corte em cm/.test(o.aviso), J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

