    exportFuncionariosSalariosPDF(); window.gerarPDF = g0;
    const cab = ((cap.match(/<thead>[\s\S]*?<\/thead>/) || [''])[0]).replace(/<[^>]+>/g, '|').replace(/\|+/g, '|');
    const linFunc = (cap.match(/Nana Teste Insalubre[\s\S]*?<\/tr>/i) || [''])[0].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
    // resumo PF (PDF)
