    const linPF = (res.match(/Nana Teste Insalubre[\s\S]*?<\/tr>/i) || [''])[0].replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ');
    // Excel
    document.querySelector('.vtab[data-v="pf"]').click(); await esp(150);
