    S.obras = [{ id: 'o1', nome: 'Obra Teste', cliente: 'C', valor: 5000, notaAcordada: 2000, status: 'andamento', _open: true, parcelas: [],
      fornecedores: [f('f1', 'Aço Exemplo', 300), f('f2', 'Cimento Teste', 1000), f('f3', '  aço  exemplo ', 200), f('f4', '', 50)] }];
