  t.ok('cheque vencido sem baixa abre o Cheques já nos vencidos', /rmAbrir\('cheques','vencidos'\)/.test(r.gaveta && r.gaveta.cheque) && JSON.stringify(r.filtro) === '[{"rm":"filtro","filtro":"vencidos"}]', J);
