teste('propostas-nuvem', async (b, t) => {
  // cada proposta no seu nó (quem grava o banco inteiro apaga o do outro);
  // gravação recusada avisa e a alteração fica guardada para subir depois;
  // a nuvem não passa por cima do que ainda não subiu daqui.
  if (!fs.existsSync(path.join(RAIZ, 'propostas_rm'))) return;
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'propostas_rm' });
  await semLogin(pg);
  const r = await pg.evaluate(async (FICT) => {
    const esp = ms => new Promise(x => setTimeout(x, ms));
    const gravados = []; let recusa = false, avisos = 0;
    window.rmNuvemErro = () => { avisos++; };
    fbDB = { ref(p) { return { set(v) { if (recusa) return Promise.reject(new Error('PERMISSION_DENIED')); gravados.push(p); return Promise.resolve(); }, remove() { gravados.push('-' + p); return Promise.resolve(); }, on() { }, off() { } }; } };
    fbAuthReady = true;
    const d = eval(FICT); docs[d.id] = d; abrir(d.id);
    const q = document.querySelector('#ficha [data-p="cliente.nome"]'); q.value = 'Outro Nome'; q.dispatchEvent(new Event('input', { bubbles: true }));
    await esp(900);
    const caminho = gravados.slice();
    recusa = true; q.value = 'Nome Recusado'; q.dispatchEvent(new Event('input', { bubbles: true })); await esp(900);
    const pendente = !!pendentes[d.id], local = JSON.parse(localStorage.getItem('rm_propostas_v1')).docs[d.id].cliente.nome;
    /* chega da nuvem uma versão mais velha desta e uma proposta de outro aparelho */
    const velha = JSON.parse(JSON.stringify(d)); velha.alterado = d.alterado - 5000; velha.cliente.nome = 'Velha';
    const outra = normalizar(eval(FICT)); outra.id = 'outra'; outra.cliente.nome = 'De Outro Aparelho';
    aplicarRemoto({ [d.id]: velha, outra });
    return { caminho, avisos, pendente, local, ficou: docs[d.id].cliente.nome, outra: docs.outra && docs.outra.cliente.nome };
  }, PROP_FICT).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r);
  t.ok('grava só o nó da proposta (propostas_rm/docs/<id>)', r.caminho && r.caminho.length === 1 && /^propostas_rm\/docs\/[a-z0-9]+$/.test(r.caminho[0]), J);
  t.ok('recusa da nuvem avisa e a alteração fica no aparelho para subir', r.avisos === 1 && r.pendente && r.local === 'Nome Recusado', J);
  t.ok('versão velha da nuvem não apaga a que não subiu; proposta de outro aparelho chega', r.ficou === 'Nome Recusado' && r.outra === 'De Outro Aparelho', J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('lista-suspensa-padrao', async (b, t) => {
  // a lista de sugestões do navegador (<datalist>) abria preta, solta do
  // campo, com uma setinha no campo (peça do Propostas e Contratos). O
  // padrão é a do Recibos: cartões brancos presos embaixo do campo. O bloco
  // comum troca todo list= sozinho, em qualquer sistema.
  if (!fs.existsSync(path.join(RAIZ, 'propostas_rm'))) return;
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'propostas_rm' });
  await semLogin(pg);
  await pg.evaluate(async () => { await iniciarApp(); document.getElementById('btnNova').click(); const t = document.querySelector('#tipoTela [data-tipo="padrao"]'); if (t) t.click(); });
  await pg.waitForTimeout(200);
  const sel = '#ficha [data-p="pre.0.itens.0.desc"]';
  const antes = await pg.evaluate(s => { const i = document.querySelector(s); return { list: i.hasAttribute('list'), adotado: i.getAttribute('data-rm-lista') }; }, sel);
  await pg.click(sel);
  await pg.waitForTimeout(150);
  const aberta = await pg.evaluate(s => {
    const i = document.querySelector(s), c = document.querySelector('.rm-lista.open');
    if (!c) return { erro: 'não abriu' };
    const a = i.getBoundingClientRect(), r = c.getBoundingClientRect(), cs = getComputedStyle(c);
    const fundo = cs.backgroundColor.match(/\d+/g).map(Number);
    return { n: c.querySelectorAll('.it').length, presa: Math.abs(r.top - a.bottom) <= 4 && Math.abs(r.left - a.left) <= 2 && r.width >= Math.max(a.width, 300) - 1, claro: fundo[0] > 200 && fundo[1] > 200 && fundo[2] > 200,
      primeira: c.querySelector('.it .d').textContent };
  }, sel);
  await pg.type(sel, 'viga');
  await pg.waitForTimeout(100);
  const filtrou = await pg.evaluate(() => [...document.querySelectorAll('.rm-lista.open .it .d')].map(x => x.textContent));
  await pg.keyboard.press('ArrowDown'); await pg.keyboard.press('ArrowDown'); await pg.keyboard.press('Enter');
  await pg.waitForTimeout(250);
  const teclado = await pg.evaluate(s => ({ campo: document.querySelector(s).value, doc: docs[atualId].pre[0].itens[0].desc, fechou: !document.querySelector('.rm-lista.open') }), sel);
  // mouse, em outro campo (item da metálica)
  const sel2 = '#ficha [data-p="met.0.linhas.0.k"]';
  await pg.fill(sel2, '');
  await pg.click(sel2); await pg.waitForTimeout(150);
  await pg.click('.rm-lista.open .it:nth-child(4)'); await pg.waitForTimeout(250);
  const mouse = await pg.evaluate(s => ({ campo: document.querySelector(s).value, doc: docs[atualId].met[0].linhas[0].k }), sel2);
  // campo criado depois (linha nova) também é adotado
  const novo = await pg.evaluate(async () => { document.querySelector('[data-acao="preItem"]').click(); await new Promise(x => setTimeout(x, 100));
    const l = [...document.querySelectorAll('#ficha [data-p$=".desc"]')].pop(); return { list: l.hasAttribute('list'), adotado: !!l.getAttribute('data-rm-lista') }; });
  const J = JSON.stringify({ antes, aberta, filtrou, teclado, mouse, novo });
  t.ok('sem a lista do navegador: list= sai do campo', !antes.list && antes.adotado === 'dlPre' && !novo.list && novo.adotado, J);
  t.ok('abre presa embaixo do campo, clara, com as 7 opções', aberta.n === 7 && aberta.presa && aberta.claro, J);
  t.ok('filtra pelo que se digita', filtrou.length === 2 && filtrou.every(x => /^Viga/.test(x)), J);
  t.ok('setas + Enter escolhem e o sistema grava', teclado.campo === 'Viga de concreto armado 20x50 cm' && teclado.doc === teclado.campo && teclado.fechou, J);
  t.ok('clique escolhe e o sistema grava', mouse.campo === 'Telha de cobertura' && mouse.doc === 'Telha de cobertura', J);
  const sem = repos().filter(r => fs.readFileSync(path.join(RAIZ, r, 'index.html'), 'utf8').indexOf('LISTA DE SUGESTÕES PRESA AO CAMPO') < 0);
  t.ok('o bloco está em todos os sistemas', !sem.length, sem.join(', '));
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('central-enxuta-arquiteta', async (b, t) => {
  // a arquiteta entrou na Central do mesmo programa em que o dono estava e
  // viu os cheques, o a receber e os gráficos dele (o resumo ficava em
  // window ao trocar de conta). E a Central dela não precisa do painel da
  // empresa, do Acompanhamento nem das notificações: só o sistema dela.
  if (!fs.existsSync(path.join(RAIZ, 'central_rm'))) return;
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'central_rm' });
  const r = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms));
    const vis = id => { const e = document.getElementById(id); if (!e) return null; const cs = getComputedStyle(e); return cs.display !== 'none' && cs.visibility !== 'hidden'; };
    document.querySelectorAll('#lock-screen').forEach(e => e.classList.add('hidden'));
    /* o dono: resumo montado */
    CURRENT_EMAIL = 'evertonluis4523@gmail.com';
    window.RM_DADOS = { cheques: { vencidos: [{ valor: 63000 }], carteira: [], totalVencido: 63000 } };
    window.RM_GRAFICOS = '<div class="rm-grid">GRAFICO-DO-DONO</div>';
    window.RM_ORIENTACOES = [{ s: 'crit', t: 'ponto do dono' }];
    document.dispatchEvent(new CustomEvent('rm:dados')); await esp(50);
    const antes = { graf: (document.getElementById('dash-graf') || {}).innerHTML || '', stats: (document.getElementById('dash-stats') || {}).textContent || '' };
    aplicarCentralEnxuta();
    const dono = { acomp: vis('btn-acomp'), notif: vis('btn-notif'), tel: vis('btn-links'), stats: vis('dash-stats') };
    /* saiu o dono: o resumo sai junto */
    if (typeof window.rmPainelLimpa !== 'function') return { antes, dono, erro: 'sem rmPainelLimpa' };
    window.rmPainelLimpa();
    /* entra a arquiteta */
    CURRENT_EMAIL = 'arquitetarm@rmestruturas.com.br';
    aplicarCentralEnxuta(); render(); await esp(50);
    let abriu = false; const oa = document.getElementById('assist-overlay'); 
    openAssistant(); await esp(50);
    abriu = !!document.querySelector('.assist-overlay.open, #assist-overlay.open, .assistant.open');
    const ela = { dados: window.RM_DADOS === undefined && window.RM_GRAFICOS === undefined && window.RM_ORIENTACOES === undefined,
      graf: (document.getElementById('dash-graf') || {}).innerHTML || '', stats63: /63/.test((document.getElementById('dash-stats') || {}).textContent || ''),
      acomp: vis('btn-acomp'), notif: vis('btn-notif'), tel: vis('btn-links'), stats: vis('dash-stats'), graf_v: vis('dash-graf-block'), abriu,
      menu: allSystems().map(s => s.id), enxuta: rmCentralEnxuta(), donoEnxuto: rmCentralEnxuta('evertonluis4523@gmail.com') };
    return { antes, dono, ela };
  }).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r).slice(0, 1500);
  t.ok('o dono vê o painel, o Acompanhamento e o sino', !r.erro && r.antes.graf.includes('GRAFICO-DO-DONO') && r.dono.acomp && r.dono.notif && r.dono.tel && r.dono.stats, J);
  t.ok('ao trocar de conta o resumo do painel sai junto (nada do dono para a próxima)', r.ela && r.ela.dados && !r.ela.graf.includes('GRAFICO-DO-DONO') && !r.ela.stats63, J);
  t.ok('Central da arquiteta: sem painel da empresa, Acompanhamento e notificações', r.ela && !r.ela.acomp && !r.ela.notif && !r.ela.tel && !r.ela.stats && !r.ela.graf_v && !r.ela.abriu, J);
  t.ok('só o sistema dela no menu; o dono não fica enxuto', r.ela && r.ela.menu.join() === 'propostas' && r.ela.enxuta && !r.ela.donoEnxuto, J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

