teste('instalador-atalho-sempre', async (b, t) => {
  // no PC de uma usuária a Central foi instalada e o ícone não apareceu na
  // área de trabalho: o instalador só criava o atalho na primeira instalação,
  // e atualização não o recriava. Agora recria em toda instalação/atualização.
  const arq = path.join(RAIZ, 'central_rm', 'package.json');
  if (!fs.existsSync(arq)) return;
  const n = (JSON.parse(fs.readFileSync(arq, 'utf8')).build || {}).nsis || {};
  t.ok('rodar o instalador de novo recria o atalho da área de trabalho, mesmo apagado', n.createDesktopShortcut === 'always', JSON.stringify(n));
  t.ok('atalho no menu Iniciar, com o nome RM Central', n.createStartMenuShortcut !== false && n.shortcutName === 'RM Central', JSON.stringify(n));
  t.ok('o instalador continua perguntando onde instalar (não é o de um clique)', n.oneClick === false, JSON.stringify(n));
  // o "always" só vale ao rodar o instalador de novo; a atualização automática
  // passa pelo customInstall, que recria o atalho se ele sumiu
  const nshArq = path.join(RAIZ, 'central_rm', 'build', 'installer.nsh'), nsh = fs.existsSync(nshArq) ? fs.readFileSync(nshArq, 'utf8') : '';
  const ci = (/!macro customInstall([\s\S]*?)!macroend/.exec(nsh) || [])[1] || '';
  t.ok('atualização automática recria o atalho da área de trabalho se sumiu', /IfFileExists "\$DESKTOP\\RM Central\.lnk"[\s\S]*CreateShortCut "\$DESKTOP\\RM Central\.lnk" "\$INSTDIR\\RM Central\.exe"/.test(ci), ci.slice(-300));
});

teste('site-unico-montagem', async (b, t) => {
  // a fila do GitHub Pages parou por mais de uma hora (19/10/2026) e
  // ninguém recebia a versão nova. O site único (rm-sistemas, no Cloudflare)
  // é montado por monta_site.py: todos os sistemas, cada um na sua pasta,
  // sem as pastas de trabalho, e a raiz abrindo a Central.
  const ferr = path.join(RAIZ, 'central_rm', 'ferramentas', 'monta_site.py');
  if (!fs.existsSync(ferr)) return;
  const dest = fs.mkdtempSync(path.join(require('os').tmpdir(), 'rm-site-'));
  let saida = '';
  try { saida = cp.execFileSync('python3', [ferr, RAIZ, dest], { encoding: 'utf8' }); } catch (e) { saida = 'ERRO ' + e.message; }
  const sis = repos().filter(r => r !== 'rm-sistemas' && r !== 'minhas-contas');
  const faltam = sis.filter(r => !fs.existsSync(path.join(dest, r, 'index.html')));
  const sujos = [];
  // .claude/.impeccable: skills e notas de design iam para o site público
  sis.forEach(r => ['ferramentas', 'electron', 'build', 'scripts', '.claude', '.impeccable', 'PADRAO_RM.md', 'CLAUDE.md', 'package.json'].forEach(x => { if (fs.existsSync(path.join(dest, r, x))) sujos.push(r + '/' + x); }));
  const vers = JSON.parse(fs.readFileSync(path.join(dest, 'versoes.json'), 'utf8'));
  const versoesOk = sis.every(r => { const h = fs.readFileSync(path.join(RAIZ, r, 'index.html'), 'utf8'); const m = /const APP_VER='(v\d+)'/.exec(h); return !m || (vers[r] && vers[r].versao === m[1]); });
  const raizIdx = fs.readFileSync(path.join(dest, 'index.html'), 'utf8');
  const wr = fs.existsSync(path.join(dest, 'wrangler.jsonc')) ? fs.readFileSync(path.join(dest, 'wrangler.jsonc'), 'utf8') : '';
  const ign = fs.existsSync(path.join(dest, '.assetsignore')) ? fs.readFileSync(path.join(dest, '.assetsignore'), 'utf8') : '';
  const migra = fs.existsSync(path.join(dest, 'central_rm', 'migra.html'));
  t.ok('todos os sistemas no site, cada um na sua pasta', !faltam.length && /sistema\(s\) montado/.test(saida), faltam.join(', ') + ' ' + saida.slice(0, 200));
  t.ok('sem ferramentas, testes, programa e documentação', !sujos.length, sujos.join(', '));
  t.ok('versoes.json com a versão publicada de cada um', versoesOk, JSON.stringify(vers).slice(0, 300));
  t.ok('a raiz abre a Central; serve pelo Pages e pelo Workers', /url=central_rm\//.test(raizIdx) && /"directory": "\.\/"/.test(wr) && /\.git/.test(ign), wr + ign);
  t.ok('a página que leva as preferências do endereço antigo vai junto', migra);
  fs.rmSync(dest, { recursive: true, force: true });
});

teste('instalar-pagina', async (b, t) => {
  // o link que se manda para instalar o programa: rm-estruturas.pages.dev/instalar/
  // (sem o nome da conta do GitHub). O botão vai direto ao instalador mais
  // novo; sem a lista de versões, vai à página das versões.
  const pagina = path.join(RAIZ, 'central_rm', 'instalar.html'), ferr = path.join(RAIZ, 'central_rm', 'ferramentas', 'monta_site.py');
  if (!fs.existsSync(ferr)) return;
  if (!fs.existsSync(pagina)) { t.ok('página de instalação', false, 'sem central_rm/instalar.html'); return; }
  const dest = fs.mkdtempSync(path.join(require('os').tmpdir(), 'rm-site-'));
  try { cp.execFileSync('python3', [ferr, RAIZ, dest], { encoding: 'utf8' }); } catch (e) {}
  const noSite = fs.existsSync(path.join(dest, 'instalar', 'index.html'));
  fs.rmSync(dest, { recursive: true, force: true });
  t.ok('o site monta a página em /instalar/', noSite);
  const html = fs.readFileSync(pagina, 'utf8');
  const API = 'https://api.github.com/repos/evertonluis4523-afk/rm-central-instalador/releases/latest';
  const ver = async (resposta, opt) => {
    const ctx = await b.newContext(opt || {}); const pg = await ctx.newPage(); const erros = [];
    pg.on('pageerror', e => erros.push(e.message));
    await pg.route('**/*', rq => { const u = rq.request().url();
      if (u.startsWith('https://rm-estruturas.pages.dev/instalar')) return rq.fulfill({ status: 200, contentType: 'text/html', body: html });
      if (u.startsWith(API)) return resposta ? rq.fulfill({ status: 200, contentType: 'application/json', headers: { 'access-control-allow-origin': '*' }, body: JSON.stringify(resposta) }) : rq.abort();
      return rq.abort(); });
    await pg.goto('https://rm-estruturas.pages.dev/instalar/').catch(() => {});
    await pg.waitForTimeout(500);
    const r = await pg.evaluate(() => ({ href: document.getElementById('baixar').href, txt: document.getElementById('baixarTxt').textContent, info: document.getElementById('info').textContent,
      alt: [...document.querySelectorAll('a')].some(a => a.href.startsWith('https://rm-estruturas.pages.dev')), larg: document.documentElement.scrollWidth, vw: innerWidth, titulo: document.title }));
    await ctx.close(); return Object.assign(r, { erros });
  };
  const rel = { tag_name: 'v1.7.9', published_at: '2026-10-19T17:20:00Z', assets: [
    { name: 'latest.yml', browser_download_url: 'https://github.com/x/latest.yml', size: 400 },
    { name: 'RM-Central-Setup-1.7.9.exe.blockmap', browser_download_url: 'https://github.com/x/b', size: 100 },
    { name: 'RM-Central-Setup-1.7.9.exe', browser_download_url: 'https://github.com/x/RM-Central-Setup-1.7.9.exe', size: 94371840 }] };
  const ok = await ver(rel);
  t.ok('o botão baixa direto o instalador mais novo e diz a versão', /RM-Central-Setup-1\.7\.9\.exe$/.test(ok.href) && /1\.7\.9/.test(ok.txt) && /90 MB/.test(ok.info) && ok.titulo === 'Instalar a RM Central', JSON.stringify(ok));
  const sem = await ver(null);
  t.ok('sem a lista de versões, o botão leva à página das versões', /rm-central-instalador\/releases\/latest$/.test(sem.href) && /Assets/.test(sem.info), JSON.stringify(sem));
  t.ok('lembra que dá para usar no navegador, no endereço do Cloudflare', ok.alt);
  const cel = await ver(rel, { viewport: { width: 360, height: 740 } });
  t.ok('no celular nada passa da tela; sem erro na página', cel.larg <= cel.vw + 1 && !ok.erros.length && !sem.erros.length && !cel.erros.length, JSON.stringify(cel) + ok.erros.join('|'));
});

teste('programa-duas-fontes', async (b, t) => {
  // o programa baixa do Cloudflare e cai no GitHub se o Cloudflare falhar ou
  // estiver atrás da versão que o computador já tem
  const arq = path.join(RAIZ, 'central_rm', 'electron', 'fontes.js');
  if (!fs.existsSync(arq)) return;
  delete require.cache[require.resolve(arq)];
  const F = require(arq);
  const pag = v => '<html>' + 'x'.repeat(3000) + "<script>const APP_VER='v" + v + "';</script>";
  const falso = mapa => { const pedidos = []; return { pedidos, fetch: async (u) => { pedidos.push(u.split('?')[0]); const r = mapa[u.split('?')[0]];
    if (r instanceof Error) throw r; if (!r) return { ok: false, status: 404, text: async () => '' }; return { ok: true, status: 200, headers: { get: () => null }, text: async () => r }; } }; };
  const P = F.PRINCIPAL + '/recibos_rm/index.html', R = F.RESERVA + '/recibos_rm/index.html';
  const a = falso({ [P]: pag(260), [R]: pag(260) }); const ra = await F.buscar('/recibos_rm/index.html', { fetch: a.fetch, versaoLocal: 259, min: 2000 });
  const b2 = falso({ [P]: new Error('rede'), [R]: pag(260) }); const rb = await F.buscar('/recibos_rm/index.html', { fetch: b2.fetch, versaoLocal: 259, min: 2000 });
  const c = falso({ [P]: pag(255), [R]: pag(261) }); const rc = await F.buscar('/recibos_rm/index.html', { fetch: c.fetch, versaoLocal: 259, min: 2000 });
  const d = falso({ [P]: 'curto', [R]: pag(260) }); const rd = await F.buscar('/recibos_rm/index.html', { fetch: d.fetch, versaoLocal: 0, min: 2000 });
  let semNenhuma = ''; try { await F.buscar('/recibos_rm/index.html', { fetch: falso({}).fetch, min: 2000 }); } catch (e) { semNenhuma = e.message; }
  t.ok('normal: só o Cloudflare é lido', ra.base === F.PRINCIPAL && a.pedidos.length === 1, JSON.stringify(a.pedidos));
  t.ok('Cloudflare fora do ar: vem do GitHub', rb.base === F.RESERVA && rb.v === 260);
  t.ok('Cloudflare atrasado em relação ao computador: fica a mais nova (GitHub)', rc.base === F.RESERVA && rc.v === 261 && c.pedidos.length === 2);
  t.ok('página incompleta não serve', rd.base === F.RESERVA);
  t.ok('sem nenhuma fonte: erro, e o programa segue com o que tem', /HTTP 404/.test(semNenhuma), semNenhuma);
  t.ok('só baixa do site da RM', F.relativo('https://rm-estruturas.pages.dev/recibos_rm/') === '/recibos_rm' && F.relativo('https://evertonluis4523-afk.github.io/rm_contas') === '/rm_contas' && F.relativo('https://outro.site/recibos_rm/') === null);
  const main = fs.readFileSync(path.join(RAIZ, 'central_rm', 'electron', 'main.js'), 'utf8');
  t.ok('Central e sistemas no programa usam as duas fontes', (main.match(/fontes\.buscar\(/g) || []).length === 2 && /fontes\.relativo\(urlSistema\)/.test(main));
});

teste('central-site-de-origem', async (b, t) => {
  // a Central abre os sistemas pelo endereço em que ela própria foi aberta
  // (Cloudflare -> Cloudflare, GitHub -> GitHub), e no endereço novo traz
  // uma vez as preferências do antigo (tema, fundo, organização da tela)
  if (!fs.existsSync(path.join(RAIZ, 'central_rm', 'migra.html'))) return;
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'central_rm' });
  const r = await pg.evaluate(() => { let zap = ''; const wo = window.open; window.open = u => { zap = decodeURIComponent(u); return null; }; telLink('instalar', 'whats'); window.open = wo;
    return { contas: (BASE_SYSTEMS.find(s => s.id === 'contas') || {}).url, epi: (document.getElementById('tl-epi-url') || {}).textContent, instalar: (document.getElementById('tl-instalar-url') || {}).textContent, zap }; });
  /* sistema renomeado no lápis quando tudo morava no github.io: o endereço
     gravado junto não pode prender o sistema no GitHub */
  const lapis = await pg.evaluate(() => {
    CURRENT_EMAIL = 'evertonluis4523@gmail.com';
    localStorage.setItem('rm_overrides', JSON.stringify({ contas: { name: 'Contas X', url: 'https://evertonluis4523-afk.github.io/rm_contas/' },
      cheques: { url: 'https://rm-estruturas.pages.dev/controle_cheques/' }, compras: { url: 'https://outro.exemplo.com/compras/' } }));
    const u = id => (allSystems(true).find(s => s.id === id) || {}).url;
    const o = { contas: u('contas'), nome: (allSystems(true).find(s => s.id === 'contas') || {}).name, cheques: u('cheques'), compras: u('compras') };
    localStorage.removeItem('rm_overrides'); return o;
  }).catch(e => ({ erro: e.message }));
  await ctx.close();
  // chegada da passagem: grava só preferência, limpa o endereço e não repete
  const dados = Buffer.from(JSON.stringify({ rm_tema: 'escuro', rm_fundo: 'trelica', 'rm_density:pessoa@exemplo.com': 'compacta', recibos_rm_dados: 'NAO', rm_senha: 'NAO' })).toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const c2 = await abre(b, { 'sis.local': 'central_rm' }, 'index.html#rm-migra=' + dados);
  const chegou = await c2.pg.evaluate(() => ({ tema: localStorage.getItem('rm_tema'), fundo: localStorage.getItem('rm_fundo'), dens: localStorage.getItem('rm_density:pessoa@exemplo.com'),
    dado: localStorage.getItem('recibos_rm_dados'), senha: localStorage.getItem('rm_senha'), feito: localStorage.getItem('rm_migrado_reserva'), hash: location.hash }));
  await c2.ctx.close();
  // a página do endereço antigo: junta só preferência e só volta para o site da RM
  const c3 = await abre(b, { 'sis.local': 'central_rm' }, 'migra.html#volta=' + encodeURIComponent('https://outro.site/x/'), { antes: () => { try { localStorage.setItem('rm_tema', 'claro'); localStorage.setItem('recibos_rm_dados', 'segredo'); } catch (e) {} } });
  const recusou = await c3.pg.evaluate(() => ({ url: location.href, txt: document.body.textContent }));
  await c3.ctx.close();
  const c4ctx = await b.newContext(); const c4 = await c4ctx.newPage(); let foiPara = '';
  /* o # não vai na requisição: a página de chegada é servida em branco e o
     endereço completo é lido dela */
  await c4.route('**/*', rq => { const u = rq.request().url(); if (u.startsWith('http://sis.local/')) return rq.fulfill({ status: 200, contentType: 'text/html', body: fs.readFileSync(path.join(RAIZ, 'central_rm', 'migra.html')) });
    if (u.startsWith('https://rm-estruturas.pages.dev/')) return rq.fulfill({ status: 200, contentType: 'text/html', body: '<html><body>chegou</body></html>' }); return rq.abort(); });
  await c4.addInitScript(() => { try { localStorage.setItem('rm_tema', 'claro'); localStorage.setItem('recibos_rm_dados', 'segredo'); } catch (e) {} });
  await c4.goto('http://sis.local/migra.html#volta=' + encodeURIComponent('https://rm-estruturas.pages.dev/central_rm/')).catch(() => {});
  await c4.waitForTimeout(800); foiPara = c4.url(); await c4ctx.close();
  const levou = (/#rm-migra=([^&]*)/.exec(foiPara) || [])[1] || '';
  const conteudo = levou ? JSON.parse(Buffer.from(levou.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8')) : {};
  const J = JSON.stringify({ r, lapis, chegou, recusou, foiPara: foiPara.slice(0, 120), conteudo });
  t.ok('sistema editado no lápis com endereço antigo abre pelo site da Central; endereço de fora fica', lapis.contas === 'http://sis.local/rm_contas/' && lapis.nome === 'Contas X'
    && lapis.cheques === 'http://sis.local/controle_cheques/' && lapis.compras === 'https://outro.exemplo.com/compras/', J);
  t.ok('sistemas abrem no endereço em que a Central abriu', r.contas === 'http://sis.local/rm_contas/', J);
  t.ok('link da Ficha de EPI enviado sempre pelo Cloudflare, sem o nome da conta do GitHub', r.epi === 'https://rm-estruturas.pages.dev/recibos_rm/epi.html', J);
  t.ok('link de instalar o programa na Central, para enviar: Cloudflare /instalar/', r.instalar === 'https://rm-estruturas.pages.dev/instalar/' && /Instalar a RM Central/.test(r.zap) && r.zap.includes('https://rm-estruturas.pages.dev/instalar/') && !/github/.test(r.zap), J);
  t.ok('chegada: grava tema, fundo e preferência da conta; dado de sistema e senha não', chegou.tema === 'escuro' && chegou.fundo === 'trelica' && chegou.dens === 'compacta' && !chegou.dado && !chegou.senha, J);
  t.ok('chegada: marca como feita e limpa o endereço', chegou.feito === '1' && !chegou.hash, J);
  t.ok('a página do endereço antigo não manda nada para fora do site da RM', /inválido/.test(recusou.txt) && /sis\.local/.test(recusou.url), J);
  t.ok('e para o site da RM leva só a preferência', /^https:\/\/rm-estruturas\.pages\.dev\/central_rm\/#rm-migra=/.test(foiPara) && conteudo.rm_tema === 'claro' && !conteudo.recibos_rm_dados, J);
  t.ok('sem erro na página', !erros.length && !c2.erros.length, erros.concat(c2.erros).join(' | '));
});

teste('programa-antigo-com-central-nova', async (b, t) => {
  // a Central se atualiza sozinha antes do programa. O programa até 1.7.x só
  // baixava sistemas de endereço do GitHub: com a Central mandando o do
  // Cloudflare ele recusava todos, marcava fora do ar e abria a cópia velha
  // do computador (o Contas ficou parado na v59). A Central manda o endereço
  // do GitHub, que os dois programas aceitam; o novo usa só o caminho.
  if (!fs.existsSync(path.join(RAIZ, 'central_rm', 'electron', 'fontes.js'))) return;
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'central_rm' });
  const r = await pg.evaluate(async () => {
    const GH = 'https://evertonluis4523-afk.github.io';
    let alvos = null;
    window.rmDesktop = Object.assign(window.rmDesktop || {}, {
      sistemasBaixados: async () => ({}),
      /* o que o programa 1.7.x fazia: só aceita endereço do GitHub */
      atualizarSistemas: async (lista) => { alvos = lista; return { atualizados: [], falhas: lista.filter(x => !String(x.url).startsWith(GH + '/')).map(x => x.pasta), mapa: {} }; } });
    await atualizarSistemasEmDisco();
    return { alvos, foraDoAr: Object.keys(FORA_DO_AR || {}) };
  }).catch(e => ({ erro: e.message }));
  await ctx.close();
  const fontes = require(path.join(RAIZ, 'central_rm', 'electron', 'fontes.js'));
  const J = JSON.stringify(r).slice(0, 1500) + ' ' + erros.join(' | ');
  const al = (r && r.alvos) || [];
  t.ok('a Central manda os sistemas para o programa baixar', !r.erro && al.length >= 10, J);
  t.ok('pelo endereço do GitHub: o programa antigo aceita e nenhum sistema fica fora do ar', !r.erro && al.every(x => /^https:\/\/evertonluis4523-afk\.github\.io\/[\w-]+\/?$/.test(x.url)) && r.foraDoAr.length === 0, J);
  t.ok('o programa novo tira só o caminho e busca no Cloudflare primeiro', al.length && al.every(x => /^\/[\w-]+$/.test(fontes.relativo(x.url) || '')) && fontes.SITES[0] === 'https://rm-estruturas.pages.dev', J);
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
});

teste('central-propostas-arquiteta', async (b, t) => {
  // a arquiteta entra na Central e vê só Propostas e Contratos; a regra do
  // banco abre o nó para ela e para o dono, e mais ninguém; a agenda dela
  // funciona (central_lembretes/<uid>); e o nó entra na cópia de segurança.
  if (!fs.existsSync(path.join(RAIZ, 'central_rm'))) return;
  const arq = 'arquitetarm@rmestruturas.com.br';
  const regras = JSON.parse(fs.readFileSync(path.join(RAIZ, 'central_rm', 'ferramentas', 'regras_firebase.json'), 'utf8')).rules;
  const rp = regras.propostas_rm || {};
  t.ok('regra: propostas_rm para o dono e a arquiteta, só', String(rp['.read']).includes(arq) && String(rp['.write']).includes(arq) && String(rp['.read']).includes('evertonluis4523@gmail.com') && !/engenharia|rudimar/.test(rp['.read'] + rp['.write']), JSON.stringify(rp));
  t.ok('regra: a arquiteta não lê outros sistemas', ['contas_pagar', 'recibos', 'obras_rm', 'orcamentos_cadastro', 'cheques'].every(n => !JSON.stringify(regras[n]).includes(arq)));
  t.ok('regra: agenda da arquiteta liberada', JSON.stringify(regras.central_lembretes.$uid).includes(arq));
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'central_rm' });
  const r = await pg.evaluate(e => {
    const ver = (email, id) => { CURRENT_EMAIL = email; return isAllowedSystem(id); };
    const sis = BASE_SYSTEMS.find(s => s.id === 'propostas') || {};
    CURRENT_EMAIL = e; const menu = allSystems().map(s => s.id);
    return { menu, url: sis.url, local: sis.local, cat: sis.cat, dono: ver('evertonluis4523@gmail.com', 'propostas'), eng: ver('engenharia@rmestruturas.com.br', 'propostas'),
      admin: (CURRENT_EMAIL = e, isAdminUser()), backup: (window.BACKUP_SISTEMAS || []).some(x => x.nos.includes('propostas_rm')) };
  }, arq).catch(e => ({ erro: e.message }));
  const J = JSON.stringify(r);
  t.ok('menu da arquiteta: só Propostas e Contratos, sem as abas de administração', !r.erro && r.menu.join() === 'propostas' && !r.admin, J);
  t.ok('Propostas na Central (Comercial), com cópia local para o programa', r.url === 'http://sis.local/propostas_rm/' && r.local === 'systems/propostas_rm/index.html' && r.cat === 'COMERCIAL', J);
  t.ok('o dono vê, a engenharia não', r.dono && !r.eng, J);
  t.ok('propostas_rm entra na cópia de segurança', r.backup === true, J);
  const central = fs.readFileSync(path.join(RAIZ, 'central_rm', 'index.html'), 'utf8');
  t.ok('propostas_rm na lista de nós da cópia', /NOS_DADOS = \[[^\]]*'propostas_rm(\/docs)?'/.test(central));
  const sync = fs.readFileSync(path.join(RAIZ, 'central_rm', 'scripts', 'sync-systems.js'), 'utf8');
  t.ok('o programa instalado baixa o sistema novo', /propostas_rm: 'propostas_rm'/.test(sync));
  t.ok('sem erro na página', !erros.length, erros.join(' | '));
  await ctx.close();
});

teste('encostado', async (b, t) => {
  // a porcentagem dos grupos do orçamento ficava espremida na borda da caixa
  if (fs.existsSync(path.join(RAIZ, 'orcamento-rm'))) {
    const { ctx, pg, erros } = await abre(b, { 'sis.local': 'orcamento-rm' });
    const r = await pg.evaluate(() => {
      const l = document.getElementById('loginScreen'); if (l) l.style.setProperty('display', 'none', 'important');
      renderTotGroups(1000, 200, 500, 300);
      const g = document.querySelector('#totGroups .grow');
      const pc = g.querySelector('.gpct').getBoundingClientRect(), v = g.querySelector('.gv').getBoundingClientRect();
      return { pctAntesDoValor: pc.right < v.left };
    }).catch(e => ({ erro: e.message }));
    t.ok('orçamento: % junto do nome, longe da borda', !r.erro && r.pctAntesDoValor && !erros.length, JSON.stringify(r) + ' ' + erros.join(' | '));
    await ctx.close();
  }
  // "Relatório para a contabilidade" começava fora da linha dos outros títulos
  if (fs.existsSync(path.join(RAIZ, 'recibos_rm'))) {
    const { ctx, pg, erros } = await abre(b, { 'sis.local': 'recibos_rm' });
    const r = await pg.evaluate(() => {
      const l = document.getElementById('loginScreen'); if (l) l.style.setProperty('display', 'none', 'important');
      state.employees = [{ id: 'a1', nome: 'ATIVO TESTE', status: 'ativo', salario: 1 }, { id: 'd1', nome: 'DESLIGADO TESTE', status: 'desligado', salario: 1 }];
      renderEmps();
      const x = e => { const q = e.getBoundingClientRect(); return Math.round(q.left + parseFloat(getComputedStyle(e).paddingLeft)); };
      const des = document.querySelector('#empOcultos .section-lab'), rel = [...document.querySelectorAll('#v-func .section-lab')].find(e => /contabilidade/i.test(e.textContent));
      const zona = rel.nextElementSibling;
      return { desligados: x(des), relatorio: x(rel), formulario: x(zona) };
    }).catch(e => ({ erro: e.message }));
    t.ok('recibos: títulos da aba Funcionários na mesma linha', !r.erro && r.desligados === r.relatorio && r.relatorio === r.formulario && !erros.length, JSON.stringify(r) + ' ' + erros.join(' | '));
    await ctx.close();
  }
});

teste('tema-suave', async (b, t) => {
  // o escuro tem duas intensidades: o "escuro" (quase preto) e o "escuro
  // suave" (grafite), escolhidas por rm_tom. O botão passa por claro →
  // suave → escuro. O suave precisa ser claramente mais claro que o escuro,
  // continuar escuro, e manter o texto legível (4,5:1).
  // só na primeira carga: o addInitScript roda de novo em cada quadro que o
  // sistema abrir, e regravar a chave ali desfaria a troca feita no teste
  const antes = () => { try { if (!localStorage.getItem('rm_tom')) { localStorage.setItem('rm_tema', 'escuro'); localStorage.setItem('rm_tom', 'suave'); } } catch (e) {} };
  for (const r of repos()) {
    const { ctx, pg } = await abre(b, { 'sis.local': r }, 'index.html', { antes });
    await semLogin(pg);
    await pg.evaluate(() => { const l = document.getElementById('loginScreen'); if (l) l.style.setProperty('display', 'none', 'important'); });
    const res = await pg.evaluate(async () => {
      const esp = ms => new Promise(x => setTimeout(x, ms));
      const lum = c => { const m = (c || '').match(/[\d.]+/g); if (!m) return null;
        const f = v => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        return 0.2126 * f(+m[0]) + 0.7152 * f(+m[1]) + 0.0722 * f(+m[2]); };
      const opaco = c => { const m = (c || '').match(/[\d.]+/g); return m && m.length > 2 && (m.length < 4 || +m[3] > 0.5); };
      const fundo = el => { for (; el && el.nodeType === 1; el = el.parentElement) { const c = getComputedStyle(el).backgroundColor; if (opaco(c)) return c; } return 'rgb(255,255,255)'; };
      const erros = [], central = !!document.getElementById('theme-grid');
      const tom = () => document.body.getAttribute('data-tom') || document.documentElement.getAttribute('data-tom');
      if (document.body.getAttribute('data-theme') !== 'escuro' || tom() !== 'suave') erros.push('abriu sem o suave (' + document.body.getAttribute('data-theme') + '/' + tom() + ')');
      await esp(900);
      const ySuave = lum(fundo(document.body));
      const txt = getComputedStyle(document.body).color, ct = (Math.max(lum(txt), ySuave) + 0.05) / (Math.min(lum(txt), ySuave) + 0.05);
      if (ct < 4.5) erros.push('texto do corpo em ' + ct.toFixed(2) + ':1 no suave');
      if (central) { window.setTheme('escuro'); } else { window.rmTema('escuro'); }
      await esp(900);
      const yForte = lum(fundo(document.body));
      if (!(ySuave >= 0.015 && ySuave <= 0.08)) erros.push('fundo do suave fora da faixa: ' + (ySuave || 0).toFixed(4));
      if (!(ySuave > yForte * 1.8)) erros.push('suave não é mais claro que o escuro (' + (ySuave || 0).toFixed(4) + ' × ' + (yForte || 0).toFixed(4) + ')');
      if (central) {
        if (!document.querySelector('[data-theme-chip="suave"]')) erros.push('sem a opção "Escuro suave" na Aparência');
      } else {
        const seq = []; window.rmTema('claro');
        for (let i = 0; i < 5; i++) { window.rmTemaAlterna(); seq.push(document.documentElement.getAttribute('data-theme') + '/' + (tom() || '')); }
        if (seq.join(' ') !== 'escuro/suave escuro/nitido escuro/forte escuro/jarvis claro/forte' && seq.join(' ') !== 'escuro/suave escuro/nitido escuro/forte escuro/jarvis claro/') erros.push('botão fora da ordem claro → suave → nítido → escuro → Jarvis: ' + seq.join(' '));
      }
      return erros;
    }).catch(e => ['avaliação: ' + e.message]);
    t.ok(r, !res.length, res.join(' | '));
    await ctx.close();
  }
});

teste('tema-escuro-nitido', async (b, t) => {
  // "Gosto do tema preto, porém acho difícil enxergar com clareza": no escuro
  // o texto principal (0,83) e o de apoio (0,78) saíam quase do mesmo cinza,
  // sobre um fundo quase preto. O "escuro nítido" (rm_tom 'nitido') leva o
  // principal quase a branco, deixa o de apoio um degrau abaixo e tira o
  // fundo do preto -- sem nenhum texto abaixo de 4,5:1.
  const antes = () => { try { if (!localStorage.getItem('rm_tom')) { localStorage.setItem('rm_tema', 'escuro'); localStorage.setItem('rm_tom', 'nitido'); } } catch (e) {} };
  for (const r of repos()) {
    const { ctx, pg } = await abre(b, { 'sis.local': r }, 'index.html', { antes });
    await semLogin(pg);
    await pg.evaluate(() => { const l = document.getElementById('loginScreen'); if (l) l.style.setProperty('display', 'none', 'important'); });
    const res = await pg.evaluate(async () => {
      const esp = ms => new Promise(x => setTimeout(x, ms));
      // cor em "color(srgb 0.99 0.56 0.47)" vem de 0 a 1 (a mistura de cores
      // escreve assim); "rgb(...)" de 0 a 255
      const lum = c => { const m = (c || '').match(/[\d.]+/g); if (!m) return null; const k = /^color\(srgb/.test(c) ? 255 : 1;
        const f = v => { v = v * k / 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        return 0.2126 * f(+m[0]) + 0.7152 * f(+m[1]) + 0.0722 * f(+m[2]); };
      const opaco = c => { const m = (c || '').match(/[\d.]+/g); return m && m.length > 2 && (m.length < 4 || +m[3] > 0.5); };
      const fundo = el => { for (; el && el.nodeType === 1; el = el.parentElement) { const c = getComputedStyle(el).backgroundColor; if (opaco(c)) return c; } return 'rgb(255,255,255)'; };
      const cr = (a, b) => (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
      const erros = [], central = !!document.getElementById('theme-grid');
      const tom = () => document.body.getAttribute('data-tom') || document.documentElement.getAttribute('data-tom');
      if (document.body.getAttribute('data-theme') !== 'escuro' || tom() !== 'nitido') erros.push('abriu sem o nítido (' + document.body.getAttribute('data-theme') + '/' + tom() + ')');
      await esp(900);
      const mede = () => { const bg = lum(fundo(document.body)), tx = lum(getComputedStyle(document.body).color); let pior = 99, qual = '';
        document.querySelectorAll('body *').forEach(e => { if (![...e.childNodes].some(n => n.nodeType === 3 && n.textContent.trim())) return;
          const rc = e.getBoundingClientRect(); if (!rc.width || !rc.height || rc.top > innerHeight || rc.bottom < 0) return;
          const cs = getComputedStyle(e); if (cs.visibility === 'hidden' || +cs.opacity < 0.2) return;
          const v = cr(lum(cs.color), lum(fundo(e))); if (v < pior) { pior = v; qual = e.textContent.trim().slice(0, 30); } });
        const ap = getComputedStyle(document.body).getPropertyValue('--text-muted').trim();
        return { bg, tx, pior, qual, apoio: ap ? Math.round(lum(ap.startsWith('#') ? 'rgb(' + [1, 3, 5].map(i => parseInt(ap.slice(i, i + 2), 16)).join(',') + ')' : ap) * 1000) / 1000 : null }; };
      const N = mede();
      if (central) window.setTheme('escuro'); else window.rmTema('escuro');
      await esp(900);
      const F = mede();
      if (!central && !(N.tx > F.tx * 1.15)) erros.push('texto principal não ficou mais claro que no escuro (' + N.tx.toFixed(3) + ' × ' + F.tx.toFixed(3) + ')');
      // na Central o texto principal já era quase branco: o apagado era o de apoio
      if (central && !(N.apoio > F.apoio * 1.5)) erros.push('texto de apoio da Central não clareou (' + N.apoio + ' × ' + F.apoio + ')');
      if (!(N.bg > F.bg * 1.2 && N.bg < 0.03)) erros.push('fundo não saiu do preto ou clareou demais (' + N.bg.toFixed(4) + ' × ' + F.bg.toFixed(4) + ')');
      if (N.pior < 4.5) erros.push('texto abaixo de 4,5:1 no nítido: ' + N.pior.toFixed(2) + ' (' + N.qual + ')');
      if (central) {
        if (!document.querySelector('[data-theme-chip="nitido"]')) erros.push('sem a opção "Escuro nítido" na Aparência');
        window.setTheme('nitido'); if (localStorage.getItem('rm_tom') !== 'nitido' || localStorage.getItem('rm_tema') !== 'escuro') erros.push('a Central não espalha o nítido (' + localStorage.getItem('rm_tema') + '/' + localStorage.getItem('rm_tom') + ')');
      } else {
        // a Central manda o nítido pela mensagem; o sistema aplica
        window.rmTema('claro'); window.postMessage({ rm: 'tema', tema: 'escuro', tom: 'nitido' }, '*'); await esp(300);
        if (tom() !== 'nitido') erros.push('mensagem da Central com o nítido não aplicou (' + tom() + ')');
      }
      return erros;
    }).catch(e => ['avaliação: ' + e.message]);
    t.ok(r, !res.length, res.join(' | '));
    await ctx.close();
  }
});

teste('central-tema-jarvis', async (b, t) => {
  // "uma opção na Central como um tema estilo Jarvis, com movimentos": o 5º
  // item da Aparência (ciano com a marca laranja). Abre com a inicialização
  // TODA vez (um clique ou uma tecla pula, e ela sai sozinha), o reator gira
  // atrás do painel e a varredura corre na tela. Com o movimento reduzido do
  // aparelho e no celular não há abertura; trocar de tema tira tudo; o
  // sistema aberto por cima recebe o tom, e o reator para enquanto isso.
  const antes = () => { try { if (!sessionStorage.getItem('__jv')) { sessionStorage.setItem('__jv', '1'); localStorage.setItem('rm_tema', 'escuro'); localStorage.setItem('rm_tom', 'jarvis'); } } catch (e) {} };
  const { ctx, pg, erros } = await abre(b, { 'sis.local': 'central_rm' }, 'index.html', { antes, espera: 300 });
  const prob = await pg.evaluate(async () => {
    const esp = ms => new Promise(x => setTimeout(x, ms)), e = [], bd = document.body;
    if (bd.getAttribute('data-theme') !== 'escuro' || bd.getAttribute('data-tom') !== 'jarvis') e.push('abriu sem o Jarvis (' + bd.getAttribute('data-theme') + '/' + bd.getAttribute('data-tom') + ')');
    if (!document.querySelector('.jv-boot')) e.push('sem a abertura ao abrir');
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', bubbles: true })); await esp(600);
    if (document.querySelector('.jv-boot')) e.push('uma tecla não pulou a abertura');
    if (!document.querySelector('.content-watermark .jv-reator')) e.push('sem o reator atrás do painel');
    if (!document.querySelector('.jv-scan')) e.push('sem a varredura');
    const c = (getComputedStyle(bd).backgroundColor.match(/[\d.]+/g) || []).map(Number);
    if (!(c[2] > c[0] + 12)) e.push('fundo não é o azul do Jarvis: ' + getComputedStyle(bd).backgroundColor);
    const chips = [...document.querySelectorAll('[data-theme-chip]')].map(x => x.getAttribute('data-theme-chip'));
    if (chips.join(' ') !== 'claro suave escuro nitido jarvis') e.push('Aparência fora da ordem: ' + chips.join(' '));
    const ch = document.querySelector('[data-theme-chip="jarvis"]');
    if (ch && !/Jarvis/.test(ch.textContent)) e.push('a opção não diz Jarvis');
    // o sistema aberto na Central recebe o tom
    const fr = document.createElement('iframe'); fr.srcdoc = '<p>x</p>'; document.body.appendChild(fr); await esp(200);
    const msgs = []; fr.contentWindow.postMessage = m => msgs.push(m);
    window.setTheme('claro'); await esp(100);
    if (document.querySelector('.jv-reator,.jv-scan')) e.push('no claro ficaram o reator ou a varredura');
    window.setTheme('jarvis'); await esp(100);
    if (localStorage.getItem('rm_tema') !== 'escuro' || localStorage.getItem('rm_tom') !== 'jarvis') e.push('a Central não espalha o Jarvis (' + localStorage.getItem('rm_tema') + '/' + localStorage.getItem('rm_tom') + ')');
    const ult = msgs[msgs.length - 1] || {};
    if (ult.rm !== 'tema' || ult.tema !== 'escuro' || ult.tom !== 'jarvis') e.push('o sistema aberto não recebeu o Jarvis: ' + JSON.stringify(ult));
    if (ch && !ch.classList.contains('active')) e.push('a opção Jarvis não aparece marcada');
    if (!document.querySelector('.jv-reator') || !document.querySelector('.jv-scan')) e.push('voltar ao Jarvis não repôs o reator e a varredura');
    fr.remove();
    // escolher na Aparência mostra a abertura; um clique pula
    if (ch) { ch.click(); await esp(150);
      const bt = document.querySelector('.jv-boot'); if (!bt) e.push('escolher o Jarvis não mostrou a abertura');
      else { bt.click(); await esp(600); if (document.querySelector('.jv-boot')) e.push('um clique não pulou a abertura'); } }
    // um sistema que troca o tema por dentro avisa a Central
    window.setTheme('escuro'); window.postMessage({ rm: 'tema', tema: 'escuro', tom: 'jarvis' }, '*'); await esp(200);
    if (bd.getAttribute('data-tom') !== 'jarvis') e.push('mensagem de um sistema com o Jarvis não aplicou (' + bd.getAttribute('data-tom') + ')');
    // com um sistema aberto por cima, o reator para de girar
    const lay = document.createElement('div'); lay.className = 'iframe-layer active'; document.body.appendChild(lay); await esp(50);
    const giro = document.querySelector('.jv-reator .a1');
    if (!giro || getComputedStyle(giro).animationPlayState !== 'paused') e.push('o reator continua girando com um sistema aberto por cima');
    lay.remove();
    return e;
  }).catch(e => ['avaliação: ' + e.message]);
  // "toda vez que abrir": abre de novo e a abertura volta, e sai sozinha
  await pg.reload({ waitUntil: 'domcontentloaded' }); await pg.waitForTimeout(300);
  if (!await pg.evaluate(() => !!document.querySelector('.jv-boot'))) prob.push('a abertura não voltou na segunda vez');
  await pg.waitForTimeout(5600);
  if (await pg.evaluate(() => !!document.querySelector('.jv-boot'))) prob.push('a abertura não saiu sozinha');
  // movimento reduzido no aparelho: sem abertura e sem giro
  await pg.emulateMedia({ reducedMotion: 'reduce' }); await pg.reload({ waitUntil: 'domcontentloaded' }); await pg.waitForTimeout(400);
  const q = await pg.evaluate(() => ({ boot: !!document.querySelector('.jv-boot'), giro: (document.querySelector('.jv-reator .a1') ? getComputedStyle(document.querySelector('.jv-reator .a1')).animationName : 'none') }));
  if (q.boot || q.giro !== 'none') prob.push('com movimento reduzido ainda há abertura ou giro (' + JSON.stringify(q) + ')');
  // no celular: sem abertura, reator e varredura
  await pg.emulateMedia({ reducedMotion: 'no-preference' }); await pg.setViewportSize({ width: 390, height: 800 });
  await pg.reload({ waitUntil: 'domcontentloaded' }); await pg.waitForTimeout(400);
  const cel = await pg.evaluate(() => [...document.querySelectorAll('.jv-boot,.jv-reator,.jv-scan')].filter(x => getComputedStyle(x).display !== 'none').map(x => x.getAttribute('class')));
  if (cel.length) prob.push('no celular aparecem ' + cel.join(', '));
  t.ok('Jarvis na Central', !prob.length && !erros.length, prob.concat(erros).join(' | '));
  await ctx.close();
});

teste('tema-jarvis-sistemas', async (b, t) => {
  // o Jarvis nos sistemas: só as cores (azul-petróleo com ciano, a marca
  // continua laranja) e as cantoneiras nos cartões -- a abertura e o reator
  // ficam na Central, para não pesar em quem trabalha. Vem pela chave comum,
  // pela mensagem da Central e pelo botão de tema, e a porta acompanha.
  const antes = () => { try { if (!sessionStorage.getItem('__jv')) { sessionStorage.setItem('__jv', '1'); localStorage.setItem('rm_tema', 'escuro'); localStorage.setItem('rm_tom', 'jarvis'); } } catch (e) {} };
  for (const r of repos()) {
    if (r === 'central_rm') continue;
    const { ctx, pg, erros } = await abre(b, { 'sis.local': r }, 'index.html', { antes });
    const res = await pg.evaluate(async () => {
      const esp = ms => new Promise(x => setTimeout(x, ms)), e = [], h = document.documentElement;
      const tom = () => h.getAttribute('data-tom') || document.body.getAttribute('data-tom');
      const opaco = c => { const m = (c || '').match(/[\d.]+/g); return m && m.length > 2 && (m.length < 4 || +m[3] > 0.5); };
      const fundo = el => { for (; el && el.nodeType === 1; el = el.parentElement) { const c = getComputedStyle(el).backgroundColor; if (opaco(c)) return c.match(/[\d.]+/g).map(Number); } return [255, 255, 255]; };
      const azul = c => c[2] > c[0] + 8 && c[2] < 90;
      if (h.getAttribute('data-theme') !== 'escuro' || tom() !== 'jarvis') e.push('abriu sem o Jarvis (' + h.getAttribute('data-theme') + '/' + tom() + ')');
      // a porta, enquanto ninguém entrou
      const porta = document.getElementById('loginScreen');
      if (porta) { porta.classList.remove('hide'); porta.hidden = false; if (getComputedStyle(porta).display === 'none') porta.style.display = 'flex'; await esp(200);
        const pc = fundo(porta); if (!azul(pc)) e.push('porta fora do Jarvis: rgb(' + pc.join(',') + ')');
        porta.style.setProperty('display', 'none', 'important'); }
      document.querySelectorAll('#lock-screen').forEach(x => x.style.setProperty('display', 'none', 'important'));
      await esp(500);
      const bc = fundo(document.body); if (!azul(bc)) e.push('fundo não é o azul do Jarvis: rgb(' + bc.join(',') + ')');
      if (!document.getElementById('rm-tema-jarvis')) e.push('sem as cantoneiras do Jarvis');
      const card = [...document.querySelectorAll('.card,.kpi,.panel')].find(x => x.getBoundingClientRect().width > 40);
      if (card && !/gradient/.test(getComputedStyle(card).backgroundImage)) e.push('cartão sem as cantoneiras');
      if (document.querySelector('.jv-boot,.jv-reator,.jv-scan')) e.push('abertura ou reator dentro do sistema (são da Central)');
      const bt = document.getElementById('rm-bt-tema');
      if (bt && !/Jarvis/.test(bt.title)) e.push('o botão de tema não diz Jarvis: ' + bt.title);
      window.rmTema('claro'); await esp(100);
      if (document.getElementById('rm-tema-jarvis')) e.push('no claro ficaram as cantoneiras');
      window.postMessage({ rm: 'tema', tema: 'escuro', tom: 'jarvis' }, '*'); await esp(300);
      if (tom() !== 'jarvis' || !document.getElementById('rm-tema-jarvis')) e.push('mensagem da Central com o Jarvis não aplicou (' + tom() + ')');
      if (localStorage.getItem('rm_tom') !== 'jarvis') e.push('o Jarvis vindo da Central não ficou guardado (' + localStorage.getItem('rm_tom') + ')');
      return e;
    }).catch(e => ['avaliação: ' + e.message]);
    t.ok(r, !res.length && !erros.length, res.concat(erros).join(' | '));
    await ctx.close();
  }
});

teste('porta-acompanha-o-tema', async (b, t) => {
  // "As telas de login de cada sistema não estão pegando o tema escuro
  // nítido": o fundo da porta era uma cor fixa (igual no escuro, no suave e
  // no nítido), e no Obras os campos ficavam brancos com letra clara. E "a
  // tela de login no fundo deixa esse fundo com movimento também": com o
  // movimento ligado, ele aparece atrás do cartão (e volta ao corpo quando a
  // porta some).
  // o script vai como TEXTO para a página: uma função levaria só o código, sem o "tom" daqui
  const prep = (tom) => "try { if (!sessionStorage.getItem('__p')) { sessionStorage.setItem('__p', '1'); localStorage.setItem('rm_tema', 'escuro'); localStorage.setItem('rm_tom', '" + tom + "'); localStorage.setItem('rm_mov', 'cotas'); } } catch (e) {}";
  const mede = async (r, tom) => {
    const central = r === 'central_rm';
    const s = await abre(b, { 'sis.local': r }, 'index.html', { antes: prep(tom) });
    const v = await s.pg.evaluate(async (central) => {
      const esp = ms => new Promise(x => setTimeout(x, ms));
      const lum = c => { const m = (c || '').match(/[\d.]+/g); if (!m) return null; const k = /^color\(srgb/.test(c) ? 255 : 1;
        const f = v => { v = v * k / 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
        return 0.2126 * f(+m[0]) + 0.7152 * f(+m[1]) + 0.0722 * f(+m[2]); };
      const porta = document.getElementById(central ? 'lock-screen' : 'loginScreen'); if (!porta) return { sem: true };
      porta.classList.remove('hide'); porta.hidden = false; if (getComputedStyle(porta).display === 'none') porta.style.display = 'flex';
      await esp(900);
      const bgv = central ? getComputedStyle(porta).getPropertyValue('--lk-fundo').trim() : getComputedStyle(porta).backgroundColor;
      const bg = lum(bgv.startsWith('#') ? 'rgb(' + [1, 3, 5].map(i => parseInt(bgv.slice(i, i + 2), 16)).join(',') + ')' : bgv);
      // campo translúcido (a Central usa branco a 6%): mistura com o fundo da porta antes de medir
      const fundoPorta = bgv.startsWith('#') ? [1, 3, 5].map(i => parseInt(bgv.slice(i, i + 2), 16)) : (bgv.match(/[\d.]+/g) || [0, 0, 0]).slice(0, 3).map(Number);
      const opaco = c => { const m = (c || '').match(/[\d.]+/g).map(Number); const al = m.length > 3 ? m[3] : 1; return 'rgb(' + [0, 1, 2].map(k => Math.round(m[k] * al + fundoPorta[k] * (1 - al))).join(',') + ')'; };
      const campos = [...porta.querySelectorAll('input[type=email],input[type=password],input[type=text]')].filter(i => i.getBoundingClientRect().width)
        .map(i => { const c = getComputedStyle(i), a = lum(/^rgba/.test(c.backgroundColor) ? opaco(c.backgroundColor) : c.backgroundColor), x = lum(c.color); return { fundo: Math.round(a * 1000) / 1000, cr: Math.round((Math.max(a, x) + .05) / (Math.min(a, x) + .05) * 10) / 10 }; });
      const cv = document.getElementById('rmMovimento'), dentro = !!cv && cv.parentNode === porta;
      let tinta = 0; if (cv) { const d = cv.getContext('2d').getImageData(0, 0, cv.width, cv.height).data; for (let i = 3; i < d.length; i += 64) if (d[i]) tinta++; }
      const card = porta.querySelector('.login-card,.login-box,.lock-card,form') || porta, rc = card.getBoundingClientRect();
      const topo = document.elementFromPoint(rc.left + rc.width / 2, rc.top + 20);
      porta.style.display = 'none'; porta.classList.add('hide'); await esp(900);
      const volta = !!cv && cv.parentNode === document.body;
      return { bg: Math.round(bg * 10000) / 10000, campos, dentro, tinta, atras: topo !== cv, volta };
    }, central).catch(e => ({ erro: e.message }));
    v.erros = s.erros; await s.ctx.close(); return v;
  };
  for (const r of repos()) {
    const n = await mede(r, 'nitido'); if (n.sem) continue;
    const f = await mede(r, 'forte');
    const prob = [];
    if (n.erro || f.erro) prob.push(n.erro || f.erro);
    else {
      if (!(n.bg > f.bg * 1.3)) prob.push('fundo da porta igual no nítido e no escuro (' + n.bg + ' × ' + f.bg + ')');
      if (n.campos.some(c => c.fundo > 0.06 || c.cr < 4.5)) prob.push('campo claro ou ilegível no escuro: ' + JSON.stringify(n.campos));
      if (!n.dentro || n.tinta < 50 || !n.atras) prob.push('movimento não aparece atrás do cartão (dentro=' + n.dentro + ' tinta=' + n.tinta + ' atrás=' + n.atras + ')');
      if (!n.volta) prob.push('o desenho não volta para o fundo quando a porta some');
    }
    t.ok(r, !prob.length && !(n.erros || []).length, prob.join(' | ') + ' ' + (n.erros || []).join(' | '));
  }
});

teste('aparencia', async (b, t) => {
  // o Tema RM (central_rm/comum/tema-rm.html) manda na aparência: o botão
  // principal é da cor da marca e todo botão tem o canto da casa, em todos
  for (const r of repos()) {
    const { ctx, pg } = await abre(b, { 'sis.local': r });
    await pg.evaluate(() => { const l = document.getElementById('loginScreen'); if (l) l.style.setProperty('display', 'none', 'important'); });
    const res = await pg.evaluate(() => {
      const erros = [], raiz = getComputedStyle(document.documentElement);
      if (!document.getElementById('rmTemaRM')) erros.push('sem o bloco Tema RM');
      if (typeof window.rmRegistro !== 'function' || !/rm-iniciais/.test(window.rmRegistro('Teste da Silva', ''))) erros.push('sem a peça de registro (rmRegistro)');
      const marca = raiz.getPropertyValue('--rm-marca').trim().toLowerCase();
      const cx = document.createElement('i'); cx.style.color = marca; document.body.appendChild(cx);
      const rgbMarca = getComputedStyle(cx).color; cx.remove();
      const vis = e => { const q = e.getBoundingClientRect(); return q.width > 0 && q.height > 0; };
      const raios = [raiz.getPropertyValue('--rm-raio').trim(), raiz.getPropertyValue('--rm-raio-p').trim()];
      document.querySelectorAll('.btn,.btn-act,.btn-sm,.btn-mini').forEach(e => {
        if (!vis(e) || e.closest('#loginScreen')) return;
        const c = getComputedStyle(e);
        if (raios.indexOf(c.borderTopLeftRadius) < 0) erros.push('canto ' + c.borderTopLeftRadius + ' em "' + (e.textContent || '').trim().slice(0, 20) + '"');
      });
      document.querySelectorAll('.btn.primary,.btn-red,.btn.red,.btn-sm.red,.btn-act.save').forEach(e => {
        if (!vis(e) || e.closest('#loginScreen')) return;
        const c = getComputedStyle(e).backgroundColor;
        if (c !== rgbMarca) erros.push('principal com fundo ' + c + ' em "' + (e.textContent || '').trim().slice(0, 20) + '"');
      });
      return erros.slice(0, 4);
    }).catch(e => ['avaliação: ' + e.message]);
    t.ok(r, !res.length, res.join(' | '));
    await ctx.close();
  }
  if (fs.existsSync(path.join(RAIZ, 'central_rm', 'comum', 'vitrine.html'))) {
    const { ctx, pg, erros } = await abre(b, { 'sis.local': 'central_rm' }, 'comum/vitrine.html');
    const n = await pg.evaluate(() => document.querySelectorAll('#cores .cor').length).catch(() => 0);
    t.ok('vitrine do padrão visual', !erros.length && n > 5, erros.join(' | ') || ('cores: ' + n));
    await ctx.close();
  }
});



/* ------------------------------------------------------------------ */
/* EM PARALELO. A bateria roda os testes em VARIOS ao mesmo tempo (padrao:
   um por nucleo do processador, no maximo 4), cada um no seu contexto do
   navegador -- nada e' dividido entre eles. Com um por vez ela passava de
   12 minutos. O relatorio sai na mesma ordem de sempre: cada teste guarda o
   que tem a dizer e so' e' impresso quando todos os de antes ja sairam.
   RM_TESTES_PARALELO=1 volta ao um por vez (bom para caçar teste instavel). */
(async () => {
  preparaFirebase(); preparaCdn(); preparaDwg();
  const exe = process.env.CHROMIUM || (fs.existsSync('/opt/pw-browsers/chromium') ? '/opt/pw-browsers/chromium' : undefined);
  const lanca = () => chromium.launch(exe ? { executablePath: exe } : {});
  const lista = TESTES.filter(tt => !FILTRO || tt.nome.indexOf(FILTRO) >= 0);
  const N = Math.max(1, Math.min(lista.length, Number(process.env.RM_TESTES_PARALELO) || Math.min(4, require('os').cpus().length || 1)));
  const inicio = Date.now();
  let ok = 0, falhou = 0, prox = 0, impresso = 0;
  const saida = lista.map(() => null);
  const imprime = () => { while (impresso < lista.length && saida[impresso]) { process.stdout.write(saida[impresso]); impresso++; } };
  /* Cada frente tem o SEU navegador: com todos num so', um travamento dele
     derrubava os testes de todas as frentes de uma vez. Se o navegador cair
     no meio de um teste, ele e' aberto de novo e o teste roda outra vez --
     a queda e' da maquina de teste, nao do sistema. So' conta o resultado da
     rodada que terminou com o navegador de pe'. */
  const roda = async () => {
    let b = await lanca();
    while (prox < lista.length) {
      const i = prox++, tt = lista[i], t0 = Date.now();
      let txt = '', nOk = 0, nFalha = 0;
      for (let vez = 1; vez <= 2; vez++) {
        txt = ''; nOk = 0; nFalha = 0;
        const ctxT = { ok(nome, cond, det) { if (cond) { nOk++; txt += '  ✓ ' + nome + '\n'; } else { nFalha++; txt += '  ✗ ' + nome + (det ? '  — ' + det : '') + '\n'; } } };
        try { await tt.fn(b, ctxT); } catch (e) { nFalha++; txt += '  ✗ ' + tt.nome + ' quebrou: ' + e.message + '\n'; }
        if (b.isConnected()) break;
        try { await b.close(); } catch (e) {}
        b = await lanca();
        if (vez === 1) txt = '';
      }
      ok += nOk; falhou += nFalha;
      saida[i] = '\n== ' + tt.nome + '  (' + Math.round((Date.now() - t0) / 1000) + ' s)\n' + txt;
      imprime();
    }
    try { await b.close(); } catch (e) {}
  };
  await Promise.all(Array.from({ length: N }, roda));
  console.log('\n' + ok + ' ok, ' + falhou + ' falha(s).' + (falhou ? ' NÃO publique.' : '') + '  [' + Math.round((Date.now() - inicio) / 1000) + ' s, ' + N + ' em paralelo]');
  process.exit(falhou ? 1 : 0);
})();
